-- GENERATED by `wfj generate` from data/quest/quest-0092.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [92109] = { "はじめてのAlchemyセット", "Empty Vialを5個、Silverleafを5個、Peacebloomを5個、WestfallのMoonbrookにある納屋の中にいる、錬金術師を目指す若者のところへ持って行って下さい。", "えっと……こんにちは、旅人さん。知らない人と話しちゃいけないんだけど……ねえ、リュックから飛び出してるそのピカピカの瓶は何のため？ 錬金術師なの？ すっごーい！\n\n大きくなったら、私も錬金術師になりたいの。パパは自分の薬草で遊ばせてくれないんだ。危ないからだって。\n\nでも、今から勉強を始めたいの。材料を集めてきてくれないかな、お願い？", nil, nil, 0xea2205a4, 0x2dcf0552, 0x3ea4b9d3, nil, nil, "...mm", nil, nil, 0x543226a7, nil, nil },
  [92110] = { "はじめての本物のポーション", "WestfallのMoonbrookの納屋の中にいる若き錬金術師志望の子のために、Murloc Eyeを3個集めてください。", "わあ、私の初めてのポーション！ 最初に始めたとき、あの二つのハーブを混ぜるとポーションが真っ赤な色に変わるって知ってた？\n\n楽しかったけど、お花をいくつか混ぜるだけじゃ、パパがやってるような錬金術とは違う気がするの。パパは他の材料も使うんだよ。\n\n他に何を使えばいいかわからないから、最初に思いついたものを試してみよう！ ええと……murloc eyesとか？ すっごく気持ち悪いけど、きっと何か起きるよ。", nil, nil, 0x694e0f66, 0x5c5c86d7, 0xcdc27db4, nil, nil, "...mm" },
  [92124] = { "蔵書の棚卸し", "図書館にいるBrother Paxtonの助手、Danielと話してください。", "行方不明の本が何冊あるか確かめないと！\n\n役立たずの助手、Danielと話してきてくれ。彼ならすぐに目録を調べて、問題がどれほど深刻か教えてくれるだろう。\n\nあいつはElwynn Forestのいろいろな職業に夢中なんだ。私を手伝う大事な仕事をそっちのけで、そればかりに気を取られている。\n\n職業の話を延々とさせずに、私の本に何があったのか聞き出してくれ！", nil, "ああ、聞こえてたよ。Brother Paxtonには、koboldが修道院の下にトンネルを掘ってるって3回も警告したんだ。\n\nどうやらkoboldはたくさんの本を持っていったらしい。本棚が丸ごと空っぽになってる。Brother Paxtonがどうしてほしいのか、聞きに行ったほうがいいだろうな。\n\nせっかく来たんだから、専門技能の話をしてもいいかい？質問があれば喜んで答えるし、この辺のトレーナーを紹介することもできるよ。", 0x0231e44e, 0xe64d5a5a, 0x1c2a73d0, nil, 0x9453402b, "...m." },
  [92401] = { "怯えた頼み", "Ruins of LordaeronでのEdward Heartweaverの失踪を調べてください。", "夫のEdwardのことなんです……\n\n毎週出かけているLordaeronの廃墟の墓地から、まだ戻ってこないんです。Arthasが街を焼き払ったときに息子を亡くしました。あの子の亡骸を見つけてあげられなかったことで、愛するEdwardは今も罪悪感と悲しみでいっぱいなんです。魔物がはびこる廃墟を探し回るのはやめてと言ったのですが、あの人は諦めようとしません。心配しないようにしてきましたけれど、もう何日も経っているんです。\n\nあそこには私では太刀打ちできないものがいます。でも、もしあなたが引き受けてくださるなら、夫の運命を知りたいのです。", nil, "私があなたに頼んだことは公平なものではありませんでしたし、あなたがただ立ち去ったとしても不当ではなかったでしょう。ありがとう、見知らぬ方。同じように報いることはできませんが、このうちのどれかを受け取っていただければ幸いです。\n\nまたお会いするときは、こんな悲しみのない形でありますように。", 0xa5170225, 0x5b830c47, 0xd111ed70, nil, 0x35199624, "...m." },
  [92415] = { "愛していると忘れないで", "Blood-Stained LetterをStormwind CityにいるOrphan Matron Nightingaleのところへ持って行ってください。", "<引き裂かれ、汚れた羊皮紙の束が、アンデッドに踏み荒らされた墓地の地面でかろうじて残っていた。Heartweaver家の行方不明の子供について書かれている。Stormwind Cityの孤児院の寮母なら何か知っているかもしれない。>", "どうした、{name}？何を探しているんだ？", "Heartweaver？Heartweaver……\n\nああ！小さなJeremy Heartweaverですね。何年も前、Lordaeronが襲われた後にここへ連れて来られた子です。その襲撃で両親を二人とも亡くしたのです、かわいそうに。\n\n実は少し前に、Duskwoodに住む優しい女性の養子になったのですよ。", 0x920a601f, 0xab38aea1, 0x10864cbe, 0x093eec87, 0x9c72863a, "....." },
  [92421] = { "光の正義", "UndercityにいるMorbin Lightbaneのために、The Ruins of LordaeronでIntact Limbsを$N1個集めてください。", "Forsakenのパラディンとして、我らがDark Ladyの意志を果たしつつ、民の必要に応えるのが私の務めだ。幸いにも、その両方を成し遂げる機会がある。\n\nUndercityの上では、scourgeが今も大群でのさばっている。我らの軍勢は土地を取り戻そうとして減っていき、腐った肉は繋ぎ直せない。代わりがなければな。\n\n我らが栄光ある隊長Garek Bandarionがまだいてくれたなら、彼が何を望むか私には分かる。彼が始めたことを成し遂げ、同胞を癒やすことだ。Lordaeronのために！", "侵略してきたscourgeは、どれだけ残っている？使えそうな代わりの部品は見つかったか？", "Banshee Queenの恩寵から堕ちた者どもに、我らの裁きを受けさせよ！\n\nこの部品があれば、我らの兄弟姉妹も明日を迎える希望が持てる。Captain Bandarionも君を誇りに思うだろう。", 0x37a29ead, 0x86900340, 0x16f288f0, 0xe9eb73ab, 0x3637945c, "....." },
  [92422] = { "Rath'maelの怒り", "BrillにいるDeathguard Kristofのために、Ruins of LordaeronでRath'maelを倒してください。", "Ruins of Lordaeronの奥深くにあるLordamere Overlookから報告が入った。邪悪な霧が通りと墓地を覆い、そこにいるscourgeにある程度の隠れ蓑を与えているという。\n\n斥候によれば、霧は奴らの中に現れた新たな力、Rath'maelという名のネクロマンサーが呼び出しているらしい。こいつばかりは待っている余裕はない、{name}。\n\n仲間がいるなら呼び集めて、Forsakenのために力を貸してもらえ。この怪物を我らの地から追い出せ。", nil, "奴の同類がいずれ代わりに現れることは疑いないが、それまでに奴らの数が減ることを願うしかない。\n\nありがとう、{name}。", 0x5b21ca69, 0x89893476, 0x68ec1579, nil, 0xa8e0a5f8, "...m." },
  [92432] = { "憂慮すべき依頼", "City of Dalaran近くのImage of Archmage Moderaのもとへ報告に行く。", "Dalaranから悪い知らせを持ってまいりました。何かが我々のレイラインを乱し、街の構造体が不規則で破壊的な振る舞いをするようになったのです。\n\nこの混乱の原因はまだ分かっていません。上層評議会は、我らの結社の恥とならぬよう、この件を内密にしておくよう命じました。しかし、この茶番をいつまでも続けることはできません。今この瞬間にも、街は蹂躙されつつあるのです！\n\nArchmage Moderaが外部の助けを求めるため私を遣わしました。Lordamere Lakeのほとり、Dalaranの近くで彼女の幻影を探してください。", nil, nil, 0x551e242b, 0x959522b1, 0xa3aabff1, nil, nil, "...mm" },
  [92434] = { "街路に流れる血", "Lordamere Lakeに沿ってDalaranへ入る道を見つける。", "Dalaranの障壁が下がった原因が何であれ、街は混乱に陥っている。お前が奴らの巡回を片付けてくれた今こそ、中へ入り込んで奴らの秘密を暴く絶好の機会だ。\n\n収容所で見つけた鍵を持って、街の北の境に沿った下水道を探せ。運が良ければ、あのメイジどもは、そんな……不快な入口にまで結界を張る理由はなかっただろう。", nil, nil, 0x417b19ab, 0xcc69013d, 0xcd6942fe, nil, nil, "...mm" },
  [92454] = { "ようこそ！", "Thendal Grove Gift VoucherをDalia Windbreezeのところへ持って行ってください。", "World of Warcraftへようこそ！\n\nWorld of Warcraft Collector's Editionをご購入いただいた特別な感謝として、このgift voucherをThendal GroveのDalia Windbreezeに渡してください。冒険と栄光を求める旅に同行する、小さな仲間が贈られます。\n\n改めてありがとうございます。World of Warcraftでの滞在をお楽しみください！", nil, nil, 0xd6adcb4f, 0x498e8e33, 0x3ed9c7cd, nil, nil, "...mm" },
  [92456] = { "緑のサンプル", "Stormwind CityのShylamiirのために、City of DalaranからFel Infused Blossomを集めて下さい。", "邪魔をしに来るなら、せめて役に立ってもらおう。片付けてほしい用事がある。\n\nメイジの都市にしては、Dalaranは植物学に驚くほど関心を持っている。Kirin Torは閉じこもっているが、彼らのマナを帯びた植物のサンプルがぜひ欲しい。\n\nお前は明らかに、歓迎されない場所にいることに慣れている者だ。都市に入り込む方法を見つけられるかもしれない。もし入れたら、中央の庭園に生えているものを何でもいいから持ち帰ってくれ。", nil, nil, 0xb4915c29, 0xdc71b0cb, 0xb62ece69, nil, nil, "...mm" },
  [92457] = { "飢えたる秘術", "Dalaranの外にいるArchmage ModeraのためにCity of Dalaran内でSeeking Remnantsを$N1体、Saturated Remnantsを$N2体、Mana Echoesを$N3体倒す。", "この亀裂は、街中の多くの魔導の従僕や魔法に影響を及ぼしました。防衛を担うものも少なくありません。断片化した秘術のエネルギーが、はぐれエレメンタルを呼び寄せています。彼らはこの自由に流れる魔法に身を浸そうとしているのです。\n\n我々が結界の手入れや他の重大な事態に追われている間に、このエレメンタルの群れを間引いていただければ、Kirin Torへの大きな助けとなるでしょう。", nil, nil, 0x3d269d6e, 0xce5323ab, 0x7ce2d848, nil, nil, "...mm" },
  [92458] = { "混乱の中心", "City of Dalaran近くのImage of Archmage ModeraのためにArcane Moteを集める。", "レイラインを乱したものが何であれ、それはViolet Citadelの頂上から始まりました。上の広間から雷鳴のような轟音が響き渡り、今や我々は荒れ狂う秘術の力に圧倒されています。結界を保つだけで精一杯なのです。\n\nこれ以上手をこまねいているわけにはいきません。助けが必要です。\n\nKirin Torは内部で手一杯ですが、それでも人目につかない方法で中へ入る必要があるでしょう。この鍵を持って、街に入り込んだら城塞で私と落ち合ってください。この混乱を終わらせなければなりません。", nil, nil, 0x0ac2f4b9, 0xf57ae5b1, 0x56e8589a, nil, nil, "...mm" },
  [92459] = { "Kirin Torの友", "City of DalaranのArchmage Celindraと話す。", "評議会は我々の策略を知れば快く思わないでしょうが、結果を否定することはできません。街は落ち着きを取り戻し、我々も結界を下ろせるようになりました。\n\n朗報を届けるのはあなたこそふさわしいと思います。この欠片をViolet CitadelにいるArchmage Celindraのもとへ届けてください。", nil, nil, 0xa01b2371, 0x54834188, 0x3a8029bc, nil, nil, "...mm" },
  [92460] = { "成年", "Thendal GroveにいるRorian the Dayseekerと話してください。", "まあ、目を輝かせて、冒険への準備は万端って顔だね！ここThendal Villageでは、どんな助けだって欲しいところだから、君が来てくれて大歓迎だよ。これから起こることを思って、緊張でいっぱいなんじゃないかな。なにしろ、成人を迎えるのは一生に一度きりだからね。\n\nさあ、ここからすぐ西にある大いなる父の木の入り口へ行って、村の長のRorian the Dayseekerに会っておいで。旅の始め方を教えてくれるよ。", nil, "疾風の挨拶を送ろう、{name}。今日、そなたがshen'doreiにもたらす可能性を認められるにあたり、成人の聖遺物を授けることを光栄に思う。我らの民は、その複雑な歴史の中で大きな苦難と迫害に直面してきた。\n\n今日そなたに授けるこの聖遺物は、そなたより前の者たちが持っていた数多くのうちの1つだ。いつの日か、そなたの遺灰が風に撒かれるとき、それは別の者の手に渡り、我らの伝統を受け継いでゆくであろう。\n\nこの聖遺物を携えて行くそなたには、どこへ旅しようとも故郷の風が共にあることを知っておくがよい。", 0x09074aad, 0x47c75d71, 0xd7d2d621, nil, 0x9ab09bea, "...m." },
  [92461] = { "調和と均衡", "Thendal GroveでVuldren Juvenileを8体倒してください。", "我らの民にとって大いなる不確かさの時代だ。前例のない困難に直面し、大胆な解決が必要になるかもしれぬ。だが、ここThendal Groveでは日常のありふれた問題にも向き合わねばならぬ。例えば、最近のvuldrenの数の持続不可能な増加だ。\n\nvuldrenは我らの生態系に欠かせない存在だ。しかし、Thendal Groveのすべての生き物が分かち合う繊細な調和を保つには、偏りを正さねばならぬ。\n\n東へ向かい、そこにいるvuldrenを間引いてくれ。", nil, "Zephrasへの奉仕に感謝する、若き{class}よ。\n\nvuldrenは普段はとてもおとなしいが、Zephrasに棲む動物たちは風に乗る魔力の均衡が崩れると、それを感じ取る。放っておけば、危険で予測のつかない行動につながりかねない。", 0xe894e8ee, 0xa0a3f81d, 0xa21181a9, nil, 0x65e69857, "...m." },
  [92462] = { "害虫蔓延の調査", "Thendal GroveでPesky Cirrusfliesを8体倒してください。", "最近、うちのレンジャーの一人が、ここThendal Groveでcirrusfliesが大量発生していると報告してきた。\n\ncirrusfliesの群れは大きくなりすぎると危険になりうる。どうかGroveの東の端へ向かい、できるだけ多く駆除してくれ。", nil, "君を覆う虫のはらわたの量からすると、これはかなりの大発生に違いない。", 0x79cd311b, 0xbb00ccfb, 0x08bf04cb, nil, 0x4468b320, "...m." },
  [92463] = { "Cirrusflyの女王", "Thendal GroveでCirrusfly Queenを倒してください。", "森にこの虫がそれほどうじゃうじゃいるなら、働き虫を倒すだけでは足りないだろう。\n\n森の奥へ進んで、女王を見つけてくれ。巣の近くにいて、もっと大きく凶暴な兵隊に囲まれているはずだから、気をつけてな。\n\n倒したらここへ戻ってきてくれ。これで、このあたりで考える問題が1つ減る。", "Cirrusfliesを甘く見ちゃいけないよ。危なそうには見えないかもしれないけど、大きいやつには気をつけないと。大きければ大きいほど、凶暴なんだ！", "見事だ、{name}。この「冒険者」稼業がうまくいかなくても、君なら立派なレンジャーになれるだろう。", 0x83a6ddbe, 0x682745f5, 0x7e74d152, 0x859bcc90, 0xc4ee2556, "....." },
  [92464] = { "エレメンタルの騒乱", "Thendal GroveのYala Windwatcherと話して下さい。", "精霊の恩人たちが去ってから、我々は1つの騒ぎから次の騒ぎへと移っているだけのようだ。今直面している問題は、北東の立石の近くにいる風の顕現たちが興奮していることだ。\n\nかつてここに住んでいた知性ある風の精霊とは違い、この単純な精たちは真の自我を持たず、周囲の生き物の力や感情、意図にそのまま反応する。\n\n弟子のYala Windwatcherが様子を見に行った。彼女を探して、何が分かったか聞いてきてくれ。", nil, "Rorianに言われて来たのか？よし。手を貸してもらえると助かる。", 0x9b167222, 0x94de46d6, 0x7eb11290, nil, 0x6e32d6cc, "...m." },
  [92465] = { "扇動者たち", "Thendal GroveでRoiling Windを$N1体とAl'Aketh Convertを$N2人倒してください。", "Al'Aketh cultはこの島の災いだ。この教団の者たちこそ、ここに住む単純な風の精たちを興奮させ、凶暴にしている張本人に違いない。\n\n残念だが、誰かを傷つける前にここで荒れ狂う風を散らさねばならない。そして教団に、この森では歓迎されないとはっきり知らしめる必要もある。\n\n力を貸してくれるか、{class}？", nil, "この森でshen'doreiの血を流すのは心が痛むが、なすべきことはなさねばならない。", 0xbed3e8bb, 0xcd6603dd, 0x1f47f35d, nil, 0x04fad858, "...m." },
  [92466] = { "大地の呼び声", "Signet of AkirをWindshaper Boroのところへ持って行ってください。", "我らの繁栄の多くは風の元素のおかげだが、我らの歩む道は、4つの主要な元素すべての呼び声に従い、それぞれの試練を受けることを求める。だが、最初の試練を本格的に始める前に、そなたの決意の強さを示さねばならぬ。\n\n東の立石へ向かえ。Al'Akethの改宗者の一団がそこで目撃されており、追い払わねばならぬ。そこの教団員と対決し、そなたの行いの証として、奴らの印章を1つ持ってきてくれ。", "Al'Aketh教団は、我らの故郷にとって最も直接的で差し迫った危険だ。ますます過激になる奴らの行いは我らの社会を不安定にし、ただでさえ弱まっていた4つの風の精霊との繋がりを損なった。エレメントは、我らの粘り強さと決意を示す行動を求めている。それは大地のエレメントの領域に根ざした資質なのだ。", "そなたは戻り、我が求めたものを持ち帰った。ゆえに、その根性と決意に疑いの余地はない。次の段階への準備は整っているぞ、{name}。", 0xe316c17f, 0x56d019a1, 0x6a8b0ee0, 0x14db7dfc, 0xd306b4d5, "....." },
  [92467] = { "大地の呼び声", "Rise of Spiritsを見つけ、Earth Saptaを飲んでください。", "saptaとは、我らの魂を精霊と結びつけるために作られる飲み物だ。魔法が溶け込んだこの薬は、意志の強い者に、他の誰にもできぬ形で精霊を見ることを可能にする。お前の魂は、そのsaptaが対応する精霊と結ばれる。そしてその作り方を知るシャーマンは、ごく一握りしかいない。\n\nsaptaは必ず聖なる場所で飲むもので、他の場所では決して飲まない。覚えておけ。\n\nここから北東の峠を登った先にあるRise of Spiritsを目指せ。そこでsaptaを飲めば……まあ、見るべきものが見えるだろう。", nil, "ああ……{name}……4つの風の子よ……そなたは理解を求めておる。答えを求めておる。なぜ風はそなたのもとを去ったのか？どうすれば取り戻せるのか？それは我には与えられぬ答えだ。我は風の意図も動きも知らぬゆえ。\n\nだが、大地については多くを教えられる。その強さ、その不屈を。果てしなく続くこの雲の海の高みにあっても、そなたはなお大地の生き物なのだ。4つの風の精霊と再び言葉を交わす力を見いだしたいと願うなら、これこそそなたが歩むべき道だ。", 0xe316c17f, 0xf6800b6c, 0x9e2aad43, nil, 0xd7d8f099, "...m." },
  [92468] = { "大地の呼び声", "Rough QuartzをThendal GroveにいるWindshaper Borosのところへ持って行ってください。", "このRough Quartzを我から受け取り、我らが出会った証として、そなたがWindshaper Boroと呼ぶ者へ持っていくがよい。彼がそなたのためにトーテムを作るであろう。そしてこの欠片がその心臓となる。小さく見えようとも、大きさは問題ではなく、どんなに小さなものでも多くのものより長く残りうることを、そなたはいずれ知るであろう。\n\n忍耐せよ、{name}。強くあれ。そして知恵を求めよ。これこそ元素がそなたに求めるものだ。最後には、そなたは大地と1つになるであろう――大地を敬え、大地がそなたを敬うように。", "いずれ分かるだろうが、我らの歩む道は見かけほど単純ではない。我らは風の精霊と語らうのに必要な声を探し求めているが、風はこの世界のエレメントの力の一つにすぎない。4つのエレメントすべてを理解し、そして願わくは極めることによってのみ、我らは再び風の歌を歌うための声を取り戻せるのだ。", "よし！\n\nお前のために作るトーテムは、{class}の中での地位の象徴以上のものだ。それには別の力もある。トーテムの使い道の1つは、呪文の焦点としてだ。それらの呪文は大地と結びついており、お前がより大きな知恵を得るにつれ、大地の力がさらに使えるようになる。\n\nより大きな知識を受け取る準備ができたときは、トレーナーたちが分かるだろう。\n\nだが今は、この大地のトーテムを受け取れ……", 0xe316c17f, 0x5d706269, 0x79a2fea5, 0xeff959cf, 0x10d906ec, "....." },
  [92469] = { "Rorianのもとへ", "Al'Akethの知らせを、Thendal GroveにいるRorian the Dayseekerに伝えてください。", "ここはもう十分だ、{class}。俺は残って、下にいる残党を片付ける。\n\nVillageへ戻って、Rorianに教団がいることを伝えてくれ。彼はいい顔をしないだろう。", nil, "これは実に憂慮すべきことだが、残念ながら驚くことではない。我々はしばらく前から教団の動きに気づいていたが、遠くから見守るだけにとどめていた。立石の近くで風の精霊を刺激したのは、明らかに奴らの行動が一段階上がったことを示している。\n\nThendal Groveのために困難だが必要な務めを果たしてくれたな、{name}。感謝する。", 0xd40ca8eb, 0x40558191, 0xc0e405c7, nil, 0x6e6e0bfa, "...m." },
  [92470] = { "穢れた母獣", "Thendal GroveでUrsera Scavengerを8体倒し、巣の母であるUrs'anahの首を手に入れてください。", "Rorianから、私があなたを見ていたと聞いたでしょう。今、あなたに決意の試練を授けます。ただし、警告しておきます――それはあなたを大きな危険へ送り込むことになります。\n\n南の洞窟へ行ってください。そこにいるurseraの数を減らし、レンジャーたちが「Urs'anah」と呼ぶ、彼らの女家長を見つけてください。彼女を倒し、その死の証を持ってきてください。それを成し遂げれば、あなたは自分の道で重要な一歩を踏み出したことになります。", "私が頼むことは簡単ではない。だが、Zephras Isleの役に立てるほど長く生き延びるつもりなら、もっと大きな試練に備えておかねばならない。", "実に見事だ。君は獣を倒し、侵入してきた教団員どもを打ち倒した。大いに見込みがあるが、君の道はまもなく比較的安全なThendal Villageの外へと続かねばならない。", 0x8559083b, 0x1984c594, 0x3d58e45a, 0xd112c07a, 0xf35c3528, "....." },
  [92471] = { "Aetheen of the Gales", "Thendal GroveにいるAetheen of the Galesと話してください。", "気づいていないかもしれないが、君がしてきたことはすべて、ある種の試練だった。君にこれから訪れることへの試験だ。外は広い島だ。我々の民が直面する試練を生き延びるには、Zephrasには君のような元気な若い冒険者が必要なんだ。\n\nAetheen of the Galesと呼ばれる方は、ここZephras Isleの我々の民の指導者の一人で、君のことを見ていた。君が果たさねばならない任務がある。彼女と話して詳しく聞いてくれ。", nil, "Rorianからあなたのことはよく聞いています。私のことはご存じないでしょうが、私はここZephras IsleのCouncil of Eldersの一員です。ここThendal Groveで風の流れを読みにやって来ました。また、あなたのように成人を迎えつつある若いshen'doreiを見定めるためにも来ています。\n\nでは聞かせてください。次の一歩を踏み出す準備はできていますか？Zephras Isleに仕える準備はできていますか？", 0x09ec0d2f, 0xe70eafd5, 0x8e0f8a1b, nil, 0x0c68dc34, "...m." },
  [92472] = { "次の一歩", "Shen'dar VillageにいるConstable Aondaに報告してください。", "Zephras Isleに広がる脅威の中でも最たるものの一つが、Al'Aketh Cultだ。奴らはSkywallの精霊の支配者とされるAl'Akir the Windlordを崇める狂信者どもだ。残忍で一途で、その力と野心は日に日に危険なものになっている。\n\nお前の進む道は、まもなく南のShen'dar Villageへと続く。着いたらConstable Aondaに顔を見せろ。教団がShen'darを脅かしていて、彼らは助けを必要としている。私が寄越したとAondaに伝えてくれ。", nil, "Aetheenに言われて来たのか？正直に言うと、たいした奴には見えないが、Shen'dar Villageは手を貸そうという者を拒みはしない。ましてElder Aetheen本人が送ってきた助けならなおさらだ。", 0x95c6443c, 0x8dffe20b, 0xb6601dd5, nil, 0x34e3eb4b, "...m." },
  [92473] = { "攻撃的な侵食", "Thendal GroveのScrawny UrseraからScrawny Ursera Clawを6個集めてください。", "南西のurseraの巣が急速に問題になりつつある。つい先週も、村に近づきすぎた若いurseraを、レンジャーたちが倒さねばならなかった。そいつは村の中心の長老の木の根元近くで遊んでいた少年を襲おうとしたのだ。\n\n少年が命からがら逃げられたのは幸運だった。飢えと追い詰められた状況が、この獣たちを放っておくには危険すぎる存在にしている。南へ向かい、urseraの中でも最も痩せこけたものを仕留めてくれ。終わったら、証としてその爪を持ってきてくれ。", "近頃、urseraはずっと攻撃的になった。何が変わって、こんなふうに振る舞いが変わったのだろう？", "よくやった、{class}。Rangers of the Groveは君に借りができた。", 0xa8134a87, 0xed3aad19, 0xabd8d5eb, 0x69f5dc9b, 0x39d32990, "....." },
  [92474] = { "華麗に落下", "Thendal Groveの見張り塔の頂上から飛び降り、Walk on Airの能力で落下を遅くしてください。", "やあ、{name}！ ゲームをしない？\n\nあの岩棚に上って……跳ぶだけ！ 生まれ持った空を歩く力で落ちるのを遅くして、どれだけ前まで漂っていけるか試してみて。\n\nルールは適当だし点数も関係ないけど、Rorian the Dayseekerのすぐ目の前に着地して驚かせたらボーナス点だよ！ 彼は嫌がるだろうけど、彼をかんかんにさせられたら、私は大笑いできるからね！ はは！", nil, "Myriaalには何度言えば分かるのだ、空から授かった力を無謀に使うよう他の者をそそのかすなと！\n\nとはいえ、村という比較的安全な場所で少し練習するくらいなら……許容範囲だろう。\n\nこれからは、その力を慎重に使うことを勧める。考えなしに魔力を使い果たして、本当に必要なときに使えなくなるのは望ましくないだろう。", 0x5a1c5b0a, 0x102a754b, 0xf3cf38d8, nil, 0xed218400, "...m." },
  [92479] = { "Scribbled Letter", "Scribbled Letterを読み、Northshire AbbeyにいるTordrin Stembladeと話してください。", "kobold野営地から戻ったらすぐにこれを知らせるよう頼まれていたんだ、{name}。地元のハンターのトレーナー、Tordrin Stembladeの印で封をされた手紙のようだ。ここAbbeyで他の用事に取りかかる前に、少し時間を取って読んでくれ。", "おう、わしの手紙を受け取ったか、{name}……よし。\n\n昔は、{race}が弓を手にしてるとこなんぞ死んでも見られんかったもんだ。もうそんなことはないらしいがな。Stormwindにとってはいいことだが、この辺りのkoboldsや人食いの獣にとっちゃ災難だ。", "まずは身の回りを落ち着けて、この土地の様子を覚えな。訓練が必要なときはいつでも戻ってこい。昼でも夜でもここにいるからな。\n\nこの土地はますます物騒になってる。ほかの連中と会えば、みんな何かしら手助けを必要としてるのが分かるだろうよ。腕の立つ{class}なら貸してやれる手助けさ。幸運を祈る。", 0x342ae89e, 0x0b04f03c, 0xaf9dc7c3, 0xb594010d, 0x84047297, "....." },
  [92480] = { "zzOLD UNUSED Cult Ambush", "Orders from the High PriestessをShen'Dar Villageへ持って行き、そこの責任者に渡してください。", "今倒した教団員が、Cult of Al'Akirの高位の女祭司からの命令書らしきものを落とした。Shen'dar Villageにいる密偵と、Falaath Villageという場所での教団の活動について書かれている。Shen'dar Villageの当局はこれを知りたがるだろう。", nil, nil, 0xa0dc56ab, 0xc6d5f21e, 0x56bd77c7, nil, nil, "...mm" },
  [92481] = { "秘術の学徒", "Glowing Recall Crystalを調べ、Thendal GroveにいるDorii Brightwhisperと話してください。", "君が我々のvuldrenの問題に対処している間に、ここに住むメイジのトレーナー――Dorii Brightwhisper――がこのrecall crystalを君に残していった。何か君宛ての伝言が入っているようだから、見てみてくれ。そのあと、Doriiは私のすぐ後ろの建物にいる。", "ごきげんよう、{name}。あなたの魔法の研鑽をお手伝いできることを光栄に思います。", "よく見せてごらん。ええ、あなたはきっと立派な若き{class}になるでしょう。我らの民の間で秘術の力は衰えてしまいましたが、この雲の上で過ごしてきた幾千年の間に失ったものの多くを再発見しようとする者たちもいます。あなたなら、この終わりなき秘術の知識の探求を先頭に立って導き、最後には私たちの誇りとなってくれると信じていますよ。\n\n次の一歩を踏み出したいなら、また私に話しかけてください。", 0xb3167a7d, 0x24eb4049, 0x40084095, 0x7a6bb7d5, 0xacf0d0f0, "....." },
  [92482] = { "ハンターの道", "Scribbled Noteを読んでから、Thendal GroveにいるTai'ree Farsightと話してください。", "君が我々のvuldrenの問題に対処している間に、ここに住むハンターのトレーナー――Tai'ree Farsight――がこのメモを君に残していった。彼女は村の中心近くのすぐ向こうにいる。メモを読んでから彼女を訪ねてくれ。", "<Tai'reeはそっけなくあなたにうなずいた。>", "{class}の道は危険に満ちており、最も鋭い感覚と最も素早い反射神経を持つ者だけが荒野で生き抜くことができる。君を見ていると、遠い昔、師の前に立っていた頃の自分を思い出す。君には素質があると思うが、結局のところ、それは君次第だ。\n\n次の一歩を踏み出したいなら、また私に話しかけてくれ。", 0x66968684, 0x8ac97a8b, 0x21034971, 0x2c09ed68, 0x2aa1e90f, "....." },
  [92483] = { "影こそ我が家", "Simple Noteを読んでから、Thendal Groveの見張り塔の中にいるAkeri Duskbladeと話してください。", "君が我々のvuldrenの問題に対処している間に、ここに住むローグのトレーナー――Akeri Duskblade――が君と話したいと言ってきた。このメモを残していったから、まずそれを読んで、ここ村の見張り塔の中にいる彼を訪ねてくれ。\n\n怪しげな奴だが、まあ、それは君も同じだ。うまくやっていけると思うよ。", nil, nil, 0xc76ec0d0, 0x9787d613, 0x78f1d36a, nil, nil, "...mm" },
  [92484] = { "精霊を受け入れる", "Humming Recall Crystalを調べてから、Thendal GroveにいるWindshaper Boroと話してください。", "君が我々のvuldrenの問題に対処している間に、ここに住むシャーマンのトレーナー――Windshaper Boro――がこのrecall crystalを君に残していった。調べてみてから、村の中心近くのすぐ向こうにいるBoroと話してくれ。", "風の導きがあらんことを、{name}。", "聞こえるか？風のささやきが。おそらく聞こえまい。かつて精霊たちが我らのもとを去って以来、我らに語りかけなくなったのだから。\n\n我らの中で再び4つの風の精霊との対話を求める者たちは、元素と自然界への理解を磨き、あれほど唐突に途絶えた対話を取り戻すことを切に願っている。\n\nそなたもこの道を歩み、元素を極めるか？\n\n次の一歩を踏み出したいなら、また我に話しかけるがよい。そなたを鍛えてやろう。", 0x935b0512, 0x59945334, 0x7abfcd0a, 0xabecb977, 0x6c6ded92, "....." },
  [92485] = { "自然の学徒", "Folded Parchmentを読んでから、Thendal GroveにいるXyton Silverwindと話してください。", "君が我々のvuldrenの問題に対処している間に、ここに住むドルイドのトレーナー――Xyton Silverwind――がこのメモを君に残していった。できるだけ早く読んで、それから私のすぐ後ろにあるこの大樹の一階にいるSilverwindを訪ねてくれ。\n\n彼の言葉と助言に耳を傾けるんだ。多くを教えてくれるだろう。", "ごきげんよう。私はXyton Silverwind、ドルイドの伝承の守り手です。", "Zephras Isleの動植物は、鮮やかな命が織りなす豊かな織物のようなものです。生態系が自然の調和を保つには絶え間ない均衡が必要であり、私たちドルイドはその均衡の守り手なのです。あなたには大きな可能性を感じますが、この道は容易ではありません。牙、爪、羽根、そして枝の学び手として力をつけていくには、導きが必要になるでしょう。\n\n次の一歩を踏み出したいなら、また私に話しかけてください。", 0x0911d9ff, 0xd2ab2b7f, 0xd328174b, 0x8a1a60b8, 0x03074af1, "....." },
  [92489] = { "圧倒的な力", "Stormwind CityのHigh Sorcerer Andromathのために、City of DalaranでMana Elementalを倒して下さい。", "Kirin TorはAllianceの古くからの同盟者だ。大悪魔Archimondeの手で都市が破壊されて以来、かつて誇り高かったメイジの都市は閉鎖的になり、よそ者を信用しなくなった。\n\nここ数年、彼らはDalaranの都市をかつての栄光に戻すため、再建に取り組み始めた。しかし報告によれば、暴走する秘術のエネルギーの噴出を抑えきれずにいるようだ。\n\n最も強力な同盟者の一つを失わないよう、我々は彼らがこの攻撃を退けるのを助けねばならない。", nil, nil, 0x311e78b1, 0xa949729f, 0x0b3dd36e, nil, nil, "...mm" },
  [92514] = { "Shen'dar Villageへようこそ", "Shen'dar VillageにいるIllaya AmberwindとCoriella Calmbreezeと話してください。", "君には「Windshaper」の雰囲気があるね。精霊に触れた者の近くにいると、肌に少し静電気を感じるんだ。それで分かるのさ。ここで本格的に働いてもらう前に、ここに住むWindshaperの長老、Illaya Amberwindに挨拶しておくといい。すぐ外の、町の中心近くにいるよ。\n\nああ、それとCoriella Calmbreezeにも顔を出しておいて。地元の宿屋をやっていて、必要なら宿と物資を用意してくれる。", nil, "Illayaには会ってきたか？よし。最近はHigh OrderとWindshapersの間がずいぶんぎくしゃくしてるが、ここShen'darでは礼儀は保たれてる。ここの誰もが、連中のいがみ合いよりずっと大きな問題を抱えてることを承知してるからな。\n\nさて、それが済んだところで、あんたは手を動かす仕事を探してるように見える。実は山賊のことで困っててな、手を貸してもらえないかと思ってたんだ。", 0x4c9d3c02, 0x5fceeb47, 0x1a5e7e29, nil, 0xc2e326dd, "...m." },
  [92515] = { "Prideclawsの問題", "Shen'dar HighlandsのPrideclawからPrideclaw Peltを10枚集めてください。", "山賊や狂った教団員だけでも手一杯なのに、今は丘にprideclawsもうじゃうじゃいる。村の境界に入り込み始めていて、日に日に大胆になっている。誰かのペットや子供がさらわれるのは時間の問題だ。何か悲劇が起きてからではなく、今のうちに数を減らしておくのが我々にとって慈悲というものだ。\n\n奴らの毛皮を12枚ほど持ってきてくれ。村の役に立ついろいろな品に作り替えられる。", "私に言わせれば、Prideclawsって実はちょっとかわいいと思うんだ。安全な距離からなら……もちろん、剣を持った誰かの後ろに立っていればだけどね。", "汚れ仕事じゃないなんて、言わなかっただろう？", 0x60e9e4a1, 0x42c57bf7, 0xa20f234c, 0x84dcc399, 0x6bbd94a8, "....." },
  [92516] = { "ヒッポグリフの嫌がらせ", "Shen'dar HighlandsでHippogryph Youthを8体、Hippogryph Protectorを6体、そしてHippogryph Matriarchを倒してください。", "Hippogryphの群れが最近Shen'dar Villageの南東に巣を構え、街道の旅人に大きな被害を与えている。誰かにそこへ行って数を減らしてもらいたい。", nil, nil, 0x51f3c6d8, 0x6f2bf4cf, 0xe1a423dd, nil, nil, "...mm" },
  [92517] = { "犯罪分子", "Shen'dar HighlandsでHighlands Banditを10人と、その頭目の\"Badwind\" Bennicを倒してください。", "北のそう遠くない所に、滝の裏に隠れた洞窟がある。山賊の一団がその洞窟を根城にしていることは、私もよく知っている。教団が来る前から厄介な連中だったが、今では本当の恐怖になっている。残念ながら、奴らを掃討しに行かせる人手を割けないんだ。\n\nそこへ行って、奴らを片付けてほしい。できるだけ多く倒し、できれば奴らの頭目、「Badwind」Bennicと呼ばれる者を始末してくれ。あの洞窟は危険だから、気をつけて。", nil, "山賊が散り散りになったおかげで、対処すべき問題が1つ減った。だが正直に言うと、今度は生き残った山賊が保護を求めて教団に走り、ますます憂慮すべき奴らの数をさらに増やすんじゃないかと心配している。\n\nそれでも、勝てるところで勝ちを拾っていくさ。", 0x40976c8d, 0xe1a7ec6c, 0x08ef374d, nil, 0x27e1dac8, "...m." },
  [92519] = { "結界の補充", "Go'shek FarmのJorellの研究所でPackaged Tonicsを一箱受け取り、HammerfallのDoctor Gregory Victorのもとへ戻る。", "Apothecary Jorellは何日も前に解毒剤と霊薬をひと箱届けるはずだったのに、いまだに何も届いていない。あの愚か者は、自分の研究所と呼んでいる換気の悪い小屋で調合していて、また自分に毒を盛ったんだろう。\n\nこの区域の力になってくれるつもりなら、この仕事にはお前のほうがずっと頼りになる。\n\nここから南、少し西にあるGo'shek農場への道をたどれ。荷物はおそらく梱包されて出すばかりになっているはずだ。Jorellはいないか、自分の務めなど気にもしていないだろうがな。", nil, nil, 0x8adc3bb2, 0xd91cbe41, 0x8af3012a, nil, nil, "...mm" },
  [92528] = { "信徒たちの中で", "Falaath Villageの周辺を調べ、Shen'dar Highlandsでの教団の狙いを突き止めてください。", "君のような熱心な新入りが加わるたびに、Al'Akirの信徒はますます強くなる。見ての通り、我らの力は嵐そのものに形を与えるのだ！\n\n普段ならすぐにSkypriest Aandersのもとへ審査に送るところだが、彼は今、町の北側の宿屋で客人を迎えていて手が離せない。今はそこに近づかないでくれ。君のような髭も剃っていない新入りがそのような客人の前に出るのは不適切だ。\n\n今のところは、とにかく誰の邪魔もしないように。", nil, "Lorthuna本人がいたのか？あいつは忌々しい教団全体の首領だぞ！\n\n奴らがShen'dar Villageと西の見張り塔を狙っているなら、備えねばならん。妙なのは……なぜ見張り塔なのかだ。\n\n村なら分かるが、塔とは？ちょっとした見張り所という以外に、戦略的な意味はたいしてないはずだ。\n\nいずれにせよ、迎え撃つ準備はしておく。高地の民は、奴らが思っているほど簡単に不意を突かれはしないと思い知るだろう。", 0x204012e1, 0x8419ec91, 0xaaed2c17, nil, 0x64c8a1fa, "...m." },
  [92529] = { "Falaath Village", "Falaath Villageの入口近くにいるMissionary Jasaanに報告してください。\n\nMark of Akirの効果を失ったら、Shen'dar VillageにいるSania Silverstreamと話して効果を取り戻してください。", "あなたがAl'Akirに仕えたいと願っていることを、心から嬉しく思います。民としての我々の今の試練は、我々自身の慢心から生じたものです。我々は傲慢になり、風の恵みを当然のものと思っていました。その後に続いた停滞こそ、風の精霊たちが我々を見捨てた理由なのです。\n\n悔い改めの行いを通してのみ、我々は再び風の愛撫を感じられるのです。同じ志を持つshen'doreiの仲間を求めるなら、Falaath Villageへ行き、そこにいるMissionary Jasaanを訪ねなさい。信徒たちがあなたを新入りと分かるよう、印をつけておきましょう。", nil, "これは何だ？シスターSaniaに遣わされた、風の王に仕えんとする新たな侍祭か？まことに我らは今日、4つの風の御手に祝福されている！\n\nAl'Akirの祝福に浴さんとする者を、我らは皆歓迎する。", 0x20d8f218, 0x4a06c83e, 0x47085e11, nil, 0xa831957e, "...m." },
  [92532] = { "ウォリアーの道", "渡されたCrumpled Noteを読み、Thendal Villageの見張り塔の中にいるBlademaster Renを探してください。", "君がいない間に、ウォリアーのトレーナー――Blademaster Ren――が、君が戻ったら自分のところへよこしてほしいと頼んできた。彼女はこのメモも君のために置いていった。\n\n読んでから、村の見張り塔の中にいるBlademaster Renを訪ねてくれ。", "では、訓練を受けに来たのか？", "そなたは危険な旅に乗り出そうとしている。我らの世界は変わりつつあり、我らの民が生き延びるには、他者を導き守る意志を持つ者が必要となる。力が増すにつれ、導きが必要となるだろう。我のもとへ来るがよい。そなたの成長に合わせ、できる限り鍛えてやろう。\n\n幸運を、{name}。風がそなたを導かんことを。", 0x72377474, 0x2103fb1b, 0x3cff1264, 0x8a44f6ef, 0x95a3eb62, "....." },
  [92534] = { "jktestquest1a", nil, nil, nil, nil, 0x0b64e98b, nil, nil, nil, nil, ".mmmm" },
  [92544] = { "Al'Akethのごろつき", "Thendal GroveでAl'Aketh Bruteを6人、Al'Aketh Neophyteを4人、そしてMalduko Cloudcrushを倒してください。", "Al'Aketh cultのならず者の一団が、ここから南西の神殿の廃墟近くに住み着いている。率いているのはMalduko Cloudcrushという本物の怪物だ。この連中は間違いなく、Shrine of AkirのHigh Priestess Lorthunaによってここへ送り込まれ、旅人を襲い、我々の民を脅して教団に加わらせようとしているのだ。\n\n私はここの持ち場に留まって、森を出ていく旅人に危険を知らせねばならない。だが、あの教団員どもとその頭目を何とかしてくれたら、ありがたい。", nil, "ここの持ち場から飛び出して加勢したい気持ちを抑えるので精一杯だった。あのならず者どもが思い知って、さっさとここから出ていくといいんだが。\n\nありがとう、{class}。Rangers of Thendal Groveが君に感謝している。", 0x0dea7326, 0xf2db9fef, 0x02f45348, nil, 0x0dce1895, "...m." },
  [92550] = { "高地の騒乱", "Falaath Villageの廃墟へ行き、Al'Aketh Stormcallerを6人とLiving Lightningを4体倒し、Commander Cyclasの首を手に入れてください。", "ここでの最善の防御は、強力な攻撃かもしれない。今の我々の強みは、攻撃が来ると分かっていることだ。奴らが予想していないのは、我々が先に仕掛けることだ。\n\nすでに多くを頼んでしまったが、どうかFalaath Villageへもう一度向かってくれ。できるだけ多くの教団員を倒し、近づけるなら指揮官を倒してその首を持ってきてくれ。私はここに残って、住民と数少ない治安維持隊をまとめて防衛の準備をする……万が一、君が戻らなかった時のためにな。", "この狂信者どもに対して形勢を逆転させるのは、気分がいいな。", "風に感謝を、戻ってきてくれたか！\n\nSania Silverstreamは、あなたが戻る直前に町からこっそり抜け出した。きっと我々の民が武装するのを見て逃げ出したんだろう。\n\nあなたはShen'dar Villageの人々のためにすばらしいことを成し遂げてくれた。我々は大きな恩を受けた。教団が高地に戻ってきても、Shen'darがそう簡単な標的ではないと思い知るだろう。\n\n風の導きがあらんことを、{name}。", 0xac4c0e34, 0x9fc6a9c3, 0x20b41f51, 0x1a5c2079, 0x89e963fe, "....." },
  [92551] = { "Stolen Supplies", "Shen'dar HighlandsのFalaath VillageからStolen Shen'dar Suppliesを10個集めてください。", "Falaath Villageに行くかもしれないって聞いたんだけど？ そこにいる間、盗まれた私たちの補給物資の隠し場所に目を光らせておいて。\n\nAl'Akethは何か月も前から、食料やwindstonesなどいろいろな品を低地と行き来させる私たちの補給隊を襲っているんだ。もちろん山賊のせいにしているけど、結局は全部同じ場所に行き着くって、みんな分かってる。Falaathにその品が少しでも残っていたら、取り戻してくれるととても助かる。", "ここには、この物資を必要としている飢えて切羽詰まったskyborneが大勢いるんだ。", "こいつはありがたい！定期的な補給が届かなくて、ぎりぎりでやりくりしてたんだ。巡査と協力して、この補給品が一番困っている町の人々に行き渡るようにするよ。", 0x97ab9949, 0x20dd891c, 0x781e5b88, 0x016f958a, 0x6a50e0dd, "....." },
  [92553] = { "食料庫の補充", "Shen'dar Highlands各地の生き物からSmall Eggを$N1個とStrider Meatを$N2個集めてください。", "ちょっと仕事をしないか？ 君みたいな強い冒険者タイプの腕っぷしを借りたいんだ。このあたりがこんなに物騒になってきたせいで、最近は誰も狩りや採集をする暇がなくてね。この村を食べさせていくために、外へ出て新鮮な卵とstrider meatを調達してくれる人が必要なんだ。\n\n必要なものを持ってきてくれたら、私の有名なレシピを1つ喜んで教えるよ。どうだい？", "ここZephrasでどれだけ物事が変わろうと、どれだけ先が見えなくなろうと、乾かしたpeacebloomを詰めたパイプと満腹の腹にまさる慰めはない、っていつも言ってるんだ！", "この卵は手に入れるのが大変だが、風に誓って、urseraの脂で少し焼くと最高にうまいんだ！\n\n時間に余裕があって料理が好きなら、俺が覚えたコツをいくつか教えてやれるぞ。一声かけてくれれば喜んで教えるよ。", 0x5295b2aa, 0xd69fc243, 0xf0409ea7, 0x0ebed89e, 0x4e67a6e0, "....." },
  [92579] = { "Valanaarへ", "Aonda's Written ReportをValanaarにいるValennia Stormfistに届けてください。", "ひとまず、パイロンも村も無事のようだ。そこで、この報告書をValanaarのValennia Stormfistに届けてほしい。Valanaarは島の南東の端にある。Valenniaは島の治安維持隊の長で、ここで何があったかを知っておく必要がある。\n\n教団は急速に勢力を広げていて、治安維持隊はこれまで直接の衝突を避けてきたが、そんな日々はもう終わりだ。Valanaarは戦いに備えなければならない。\n\nいずれにせよ、ありがとう。Shen'darにはいつでもお前の友がいるぞ、{name}。", "Aondaからの手紙か。あの抜け目のない高地の民は、何をたくらんでいるんだ？", "<手紙を読むValenniaの表情が曇っていく。>\n\nAondaはあなたを信頼してこれを託したのね。この手紙でもあなたのことをずいぶん褒めているから、私もあなたを信頼してみるわ。話を続ける前に、ここに残っているわずかな治安維持の者たちと相談して、教団が次にここを襲った場合に備えて計画を立てなければならないの。今はValanaarでの滞在を楽しんでいて。\n\n何かすることを探しているなら、あなたのような強い若き冒険者の助けを必要としている町の人々がたくさんいるはずよ。", 0x74fef55e, 0x117fb641, 0x1bb0140d, 0xc4bd4279, 0x4cbd429f, "....." },
  [92595] = { "Windshapers", "Illaya Amberwindの話を聞いてください。", "<Illayaがあなたに温かく微笑む。>\n\nよく戻って話しに来てくれました、風の子よ。あなたが初めて私の前に現れた瞬間から、あなたがskysightに秀でていると分かっていました。驚きましたか？ シャーマンとしての修行を積んでいない者でも、この才を持つことがあるのです。\n\nさあ、Windshapersの使命、Zephrasにおける我々の苦闘の本質、そして我らが民の苦境について話しましょう。", nil, "Windshapersの使命がどれほど重要か、もう分かっただろう。再び風の精霊との対話を確立したいと願うなら、天空の眼を操る者はひとりひとりが極めて重要なのだ。\n\nAl'Akethのような内なる脅威と、ここSkywallでの我々の安全の不確かさの間で、自らの賜物を使って故郷を救い、Shen'doreiがこの苦難の時代を生き延びられるようにすることこそ、Windshapersとしての我々の責務なのだ。", 0x780f72d7, 0xc822e25f, 0x377f999c, nil, 0x60d678be, "...m." },
  [92596] = { "High Order", "席に着いて、Rathiril Sunlanceと話してください。", "あなたを取り巻く秘術のエネルギーのオーラは強い。メイジとしての手ほどきを受けていないにもかかわらずです。あなたはきっと有能な冒険者になるでしょう。たとえ呪文を唱えるための力ある言葉を一言も発することがなくとも、我らの古の魔法とのつながりは、あなたにとって恩恵にしかならないはずです。\n\nさあ、座って、私の結社のこと、ここZephrasにおける秘術の本質、そして我らが民の苦境について少し話しましょう。", nil, "High Orderの使命は、我らの民の存続に不可欠だ。我らは精霊の恩人たちに最大の敬意を払っているが、現実を直視せねばならない。彼らはもういない。我らは自分たちの力で生きていくしかないのだ。\n\nAl'Akethのような内なる脅威と、この次元における我らの安全の不確かさの間で、祖先の故郷Eldre'ThalasのHighborneの末裔として、自らの賜物を使ってshen'doreiが再び自らの足で立てるようにすることこそ、我らの宿命なのだ。", 0x022195d4, 0x8d1edbd7, 0xfb71220a, nil, 0xf653c22f, "...m." },
  [92597] = { "レイラインを読む", "Thendal Groveの地脈で、種族能力Read Ley Lineを使ってください。", "ここ元素界では、我々は秘術の力の多くを、今も足元の地中を走るレイラインから得ています。最近、これらのレイラインが地表を突き破り始め、潜在する秘術のエネルギーに、より直接的かつ強力に触れられるようになりました。\n\n北東の立石へ行ってください。そこにレイラインがあります。生まれ持った力を使い、そのエネルギーを取り込みなさい。", "highborneの息子や娘として、我らの真の力を開花させることだけが救いへの唯一の道だ。Windshapersは、無関心な異界の存在にひれ伏しているのだから、Al'Akethと大差ない。", "感じるか？そうか？よし！君は最初の一歩を踏み出した。その力があれば、多くの場所で眠っている魔力を引き出せることに気づくだろう。そうすることで様々な恩恵が得られる。深遠なものもあれば、より微妙なものもある。実際に引き出してみるまでは分からないが、それこそがこの賜物の一番の醍醐味だ……未知を既知にすることがな。\n\nこの苦難の時を生き延びるには、知識を……そして力を、揺るぎなく追い求めねばならない。", 0xb27b6c1c, 0xa07cd5b4, 0x5d755957, 0x1c118522, 0xba617b0f, "....." },
  [92598] = { "Skysightの贈り物", "Thendal GroveのElemental Convergenceで、種族能力Skysightを使ってください。", "Windshaperとして、あなたには元素の精霊たちから我々に授けられた神聖なskysightを使う力があります。村の北東の立石へ向かってください。そこで元素の合流点を見つけ、その才を使いなさい。\n\nskysightはどこでも使えますが、元素の合流点のそばで使えば、その恩恵ははるかに強くなることが分かるでしょう。そうした力の場に引き寄せられる精霊たちから、時には他の知恵を授かることもあるはずです。", nil, "筋肉と同じように、天空の眼もその賜物の力を伸ばしたいなら鍛えなければならない。天空の眼を活かして定命の世界と霊的な世界の隔たりを埋めることは、君の冒険において計り知れない価値を持つかもしれない。\n\n今日ここで学んだことを忘れないことだ。賜物を使って元素の声を聞く我らの力こそが、我らが生き延びる鍵となるかもしれないのだから。", 0x72459b2b, 0x16d8780d, 0x316bc5c0, nil, 0x0d8764c0, "...m." },
  [92640] = { "窮地", "ValanaarにいるValennia Stormfistと話し、彼女の指示に従ってください。", "教団と正面から戦うのは現実的ではないから、この機会を使って聖堂そのものを攻撃するのが最善の手だろう。Lorthunaが計画の自分の役割を果たす前に、彼女自身を盤上から除けるかもしれない。\n\nちょうど、Valenniaがしばらく前からShrineへの攻撃に備えた作戦を練っていた。唯一の問題は、助けが必要だということだ。\n\n詳しいことはValenniaと話してくれ。", nil, "今はWindshapersとHigh Orderの間の緊張が高まっている。だが、両方の集団の協力なしに、この計画をやり遂げられる望みはないのだ。", 0xbee67de8, 0xe0ffb7d6, 0x807c5f5e, nil, 0x4f07dec6, "...m." },
  [92642] = { "兵站の妨害", "Gustberry LowlandsでAl'Aketh Healerを4人とAl'Aketh Brawlerを8人倒してください。", "Valenniaは本格的な攻撃を撃退するのに、たった1人しか送ってこなかったのか……風にかけて。\n\n大した奴には見えないが、贅沢は言えない。すぐにこれを止めるには、できるだけ大きな損害を与える必要がある。私の部下たちはもう長くは持ちこたえられない。\n\n丘を下りて、奴らの補給を乱してくれ。奴らの治癒師が攻撃者を送り続けている。治癒師を片付ければ、態勢を立て直して押し返せるかもしれない。そこで他の教団員を倒してくれるのも助かる。", nil, "まだ生きていたのか？ささやかな奇跡を風に感謝すべきだろうな。", 0x4ee49cde, 0xfd87bd08, 0x9d51a92f, nil, 0x891c6ecb, "...m." },
  [92643] = { "裏切り者", "Valanaarの北西、高地に入ってすぐの家にいる教団の裏切り者を見つけてください。", "Al'Akethの中に裏切り者がいる。そいつは島に対する教団の真の狙いを知っていると言い、こちらへ寝返りたいそうだが、身の安全が保証されなければ応じないという。\n\nこの離反者は、Valanaarのすぐ北西、高地の中にある人里離れた住まいに隠れている。誰か目立たずにそこへ行き、その裏切り者を見つけて、ここまで護衛して連れてきてくれる者が必要だ。罠かもしれないが、この裏切り者の言うとおり重要な情報なら、多少の危険を冒す価値はある。", nil, "<この男は明らかに死んでいる。家の外であなたが戦った暗殺者たちに殺されたのだ。遺体を調べようとひざまずくと、何か光る物がきらりと反射しているのに気づく……>", 0x19e86215, 0xbb45643c, 0x0734bd6e, nil, 0xfe7530c0, "...m." },
  [92644] = { "不運な知らせ", "光る水晶をValanaarにいるTalanaanis Shadowsongに届けてください。", "<まだ温かい裏切り者の教団員の遺体の下に手を伸ばし、小さく青く光る水晶を拾い上げた。傷ついているようだが、まだ重要なものかもしれない。High Elder Shadowsongがこれに興味を持つかもしれない。>", "戻ったのか？それに……一人で？", "君が着いた時には、裏切り者はすでに死んでいたと？それは残念な知らせだ。\n\n<死んだ教団員の遺体から見つけた水晶を手渡す。>\n\n興味深い……", 0xfee67657, 0xd4f77d59, 0x29c73863, 0x9c8dd0dd, 0xf4127133, "....." },
  [92645] = { "the Breakerの打倒", "Gustberry LowlandsでCommander Belguilosを倒してください。", "教団の指揮官を倒さない限り、この攻撃を撃退するのは難しいだろう。Belguilos「the Breaker」と呼ばれている女で、まさに恐怖そのものだ。教団が手に負えなくなる前は治安維持隊の一員だったが、その頃から彼女は……どこかおかしかった。教団員となった今、どれほどひどくなっているか想像もつかない。\n\n君を死地に送り出すことになるかもしれないが、ここで生き延びるには誰かがBelguilosを倒さねばならない。彼女は丘のふもとの屋敷にいる。幸運を、{class}。", nil, "Belguilosが死んだ？4つの風の祝福があらんことを、{class}。\n\n結局、我々は生きてここを切り抜けられるかもしれないな。", 0xe9120191, 0x51edce72, 0x069c8615, nil, 0x3891e497, "...m." },
  [92646] = { "Lorthunaとの対決", "ポータルで頭上のRohashi Spiresへ行き、Elaadrin EvengaleとAyessa Dawnsingerに加わってHigh Priestess Lorthunaと対決してください。", "Lorthunaは何かのポータルを使って上の尖塔へ逃げた。AyessaとElaadrinが後を追って入っていった。ほんの少し前のことだ。\n\nすまないが、攻撃を1発多く食らいすぎた。私はここまでだ。ポータルを抜けて、Ayessaを見つけ、彼らがLorthunaを止めるのを手伝ってくれ。\n\nElaadrinとAyessaが呼んだという援軍がすぐに来ない限り、ここからは君一人だ。幸運を、{class}。", nil, "Valenniaと残った部隊が無事に戻れるよう、治療師を何人か送った。彼女は今、High Elderの住まいで休んでいるはずだ。\n\nMulnはすでにAzerothへ戻ったが、Windshapersのこれからと、Azerothでの我々の使命について彼と話し合った。残念ながら、島は今やかつてないほど無防備だ。これから来るものからZephrasを守る計画が必要だ。", 0x90290d9d, 0x05b5bc13, 0xc9ea1d15, nil, 0xd1f90ba8, "...m." },
  [92679] = { "血の十分の一税", "Alvarion Windfieldの話を聞き、Windfield OrchardにいるAamelia Windfieldを見つけてください。", "こ……こんにちは、見知らぬ方。有能な冒険者のようにお見受けします。私は……\n\n<Skyborneの男は顔をしかめる。明らかにひどい痛みに苦しんでいる>\n\n……仕事を探しておられないかと思いまして。私は農場を救うために戦える者を集めようと、ここValanaarへ来ました。もし興味がおありなら、Valanaarの西、低地にある果樹園にいる妻のAamelia Windfieldを訪ねてください。", "何だって？Alvarionが生きているだと？", "<Alvarionがどうなったかを説明すると、Aameliaは耳を傾ける。>\n\n少なくとも、彼がValanaarで無事にいられるのは分かったわ。\n\n旅の人、言いにくいのだけれど、うちの馬鹿な夫はたぶん、あなたを無駄死にさせるためにここへよこしただけだと思うの。少しでも分別があるなら、今すぐ立ち去るべきよ。これはあなたの戦いではないわ。", 0xa8fc6a6e, 0x914a33e3, 0x14a8cf7d, 0xefd01bb9, 0x793bb808, "....." },
  [92682] = { "役に立つこと", "Windfield OrchardでRipe Stormappleを10個集め、Hungry Banditを5人倒してください。", "あら、分別より度胸があるってわけ？ いいわ、反対はしない。\n\nFerauuとその手下どもが収穫の取り分を取りに来るのはまだ先だから、奴らが来るまで食事代として働いてもらうわ。\n\n外へ出て、今日の分のstormapplesを集めてきて。ああ、それとstormappleの木の周りに潜んでいる山賊ども……こっそりしてるつもりなのよ。全然そうじゃないけど。そいつらを倒してきて。\n\n戦いでどれだけやれるか見せてもらうわ。", "この盗賊どもは、普通の人々から盗むよりも、仲間同士で裏切り合って盗み合う方がよっぽどありそうな連中だ。賭けてもいいが、もし手下の何人かが勝手に裏切ってここへ早めに来て、収穫に手を出していたとFerauuが知ったら、奴が自分で始末するだろうさ。", "窓からあんたがあの山賊どもを倒すのを見ていたよ。悪くないね。", 0x465218e3, 0x7a8714e9, 0x7b15cb2a, 0x836efca1, 0xe39119c4, "....." },
  [92683] = { "Flutterfly Dust", "Gustberry Lowlands周辺のFlutterfliesからFlutterfly Dustを5個集めてください。", "果樹園の外れの畑に巨大なflutterfliesがいるのに気づいたでしょう？ 見た目もいいけど、他にも役に立つの。つまり、羽の粉よ。散らかるけど、たくさん集められれば家庭でいろいろ使えるの。\n\nこのFlutterfly Swatterを持っていって、あの大きな虫をひっぱたいてきて。たいていは驚いて逃げるだけだけど、たまに怒ることもあるわ。どちらにしても、お尻を振って粉の山を落としていくはずよ。", "Flutterfliesは普段はおとなしくて穏やかだけど、機嫌を損ねると時々びっくりさせられるよ。", "こいつはちょっと散らかりやすくて、そこら中に入り込むんだ。残念だけど、きっと何週間もズボンからこいつを振り落とすことになるよ。でも本当に感謝してる。何週間もやることリストに載ってたんだけど、山賊がそこら中にうろついているのに一人きりで家から離れすぎるのは大きな危険でね。\n\nこれを何に使うのかは聞かないでくれ。いろいろだよ。いろんな物やいろんなことさ。気にしないでくれ。", 0xebc0dbf4, 0x62baa758, 0x70511ad5, 0x17b2b4fc, 0x3c26d1b7, "....." },
  [92684] = { "気難しい気難しいGalestriders", "Gustberry Lowlands各地にいるOrnery GalestriderからLowlands Galestrider Tenderloinを7個集めてください。", "ただでさえ今年は収穫が少ないってのに、このあたりのgalestriderどもが果樹園に入り込んで、うちのstormappleを盗んでいくんだ。畑に出て、数を減らしてきてくれないか？\n\nでも気をつけなよ、よそ者さん。この低地のgalestriderは、高地のやつらよりでかくて気が荒いんだ。用心しな。油断してると、うまく決まった蹴り一発で、二度と起き上がれなくなるぞ。\n\n肉を持ってきてくれたら、それで温かい料理も作ってやれるよ。", "夕食にちゃんとした肉を食べたのは……そうだな、もうずいぶん前のことだ。", "大きなテンダーロインだな！向こうで本物の化け物を仕留めてきたに違いない。", 0xe003ddda, 0xac246e35, 0x00cc4ad7, 0x2e036ee0, 0x39c498db, "....." },
  [92685] = { "丘に目あり", "Gustberry LowlandsのHighwayman BanditからBlood-Stained Bandit Maskを7枚奪ってください。", "山賊どもはあちこちに野営地を持っていて、ここのすぐ北の丘にも小さいのがある。そこへ行って、頭をかち割ってきて。不意を突いて、向こうが来る前に倒せれば、勝ち目が出るくらいには形勢を互角に近づけられるかもしれない。\n\n奴らの覆面を持ってきて。血まみれなほどいいわ。", "盗賊の覆面を十分に持ってきてくれたら、それで毛布を縫ってFerauuに贈ってやろうかしら。\n\n<Aameliaは大声で笑った。>", "血まみれなほどいいと言ったら、本当にその通りにしてくれたな。いいぞ。奴らを痛い目にあわせてくれたのがよく分かる。\n\n真面目な話、ここまでしてくれたことに感謝する。何週間も、ただ終わりが来るのを待つかのように、この農場のまわりをあてもなく漂っていたんだ。また希望を持てるようになってきた気がする。\n\nFerauuとその手下どもは、もういつ来てもおかしくない。あとは出ていって奴らと向き合うだけだ。どうだ、最後まで一緒にやり遂げてくれるか？", 0x68a565d3, 0x0cc48551, 0x0d447ad8, 0x55d5b255, 0x646cb966, "....." },
  [92693] = { "踏みとどまる", "山賊の頭目と対決する準備ができたら、Aamelia Windfieldと話してください。", "あなたは私たちに戦うチャンスを与えるために、たくさんのことをしてくれた。たとえ今日死んでも、少なくとも全力を尽くしたとは分かるわ。\n\nこれが最後のチャンスよ、よそ者さん。Valanaarへ戻ってもう一日生き延びたいなら、責めはしない。\n\n一方で、本当に負け戦が好きなら、準備ができたら教えて。胸を張って出ていって、何が起きようと、それはそれよ。", "このお礼をするには、skywallじゅうのstormapplesを集めても足りないよ。", "お……終わったなんて信じられない。心臓が胸から飛び出す前に、少し落ち着かないと。", 0x50b105ba, 0x080cc4f1, 0xdb57333a, 0x0e2208f0, 0xae67af8a, "....." },
  [92698] = { "私の目的とは？", "Malfunctioning Cyclone Constructについて、Aamelia Windfieldと話してください。", "<巨大な構造体の装甲板の下から聞こえてくる言葉を聞き取ろうと、身を寄せる。>\n\n……機能エラー……\n\n……質問……\n\n……何とは……\n\n……機能……\n\n<断片的な言葉や語句が繰り返されているだけのようだ。近くの誰かがこの構造体についてもっと知っているのでは？>", nil, "あの機械のことか？何十年も畑をうろついているよ。風の精霊たちが私たちのもとを去ってからだと思う。Alvarionは、ここが果樹園になる前、あれは収穫物を市場へ運ぶか、家畜の世話をしていたんじゃないかと考えていた。でも、それは千年も前のことかもしれないけどね。\n\n昔はWindshapersがこういう機械の手入れをしていたんだ。見に来てくれるよう彼らに頼もうかと話したこともあるけど、私たちにとって差し迫った問題じゃなかった。最近はたいてい放っておいてるよ。", 0x241171d6, 0xd478b4f6, 0x3666770b, nil, 0x051eaa94, "...m." },
  [92699] = { "至高のMagister", "ValanaarにいるElaadrin Evengaleを見つけてください。", "Valanaarに着いたなら、ここにいるHigh Orderの他の仲間たちに顔を出しておきたいだろう。今のSupreme Magister、Elaadrin Evengaleとその部下たちは、Valanaarの南東の端の山荘を拠点にしている。\n\nそれと、気をつけるといい。ここではHigh OrderとWindshapersの仲が良くない。用心して、Windshapersには十分距離を置くことだ。教団だけでも心配事は十分ある。Valanaarの通りで派閥同士の暴力沙汰は許さない。", nil, "ようこそ。Rathirilから魔法の書簡で、あなたのことを知らされました。見込みがある、と書いてありましたよ。\n\nこうして目の前に立つあなたを見ると、なぜ彼が私を訪ねるよう勧めたのか分かります。あなたには生き生きとした秘術のオーラがある。必要なことを成して故郷を救うための素質を持つ者は、もはやわずかしかいません。意志を持つ者となればなおさらです。The High Orderに力を貸すだけの大胆さと強さが、あなたにありますか？\n\nそれはいずれ分かるでしょう。", 0x395f1c03, 0x81508f78, 0xc13b19e1, nil, 0x0b5b1bf3, "...m." },
  [92700] = { "Grand Skyseer", "ValanaarにいるAyessa Dawnsingerを見つけてください。", "Valanaarに着いたなら、ここにいるWindshapersの他の仲間たちに顔を出しておきたいだろう。今のGrand Skyseerとその部下たちは、Valanaarの中心近くの山荘を拠点にしている。\n\nそれと、知っておくといい。このあたりではWindshapersとHigh Orderの仲が良くない。用心して、High Orderには十分距離を置くことだ。教団だけでも心配事は十分ある。Valanaarの通りで派閥同士の暴力沙汰は許さない。", nil, "Elder Amberwindから、あなたのこと、そしてShen'dar Villageでのあなたの活躍について知らせが届きました。ここでは心から歓迎しますよ、友よ。\n\nあなたは強いオーラを持ち、明らかに精霊たちと共鳴しています。近頃は天空の目を持つ者がどんどん少なくなっています。この苦難の時を生き延びるには、Zephrasにはその才能を持つ者が必要なのです。あなたが私のもとへたどり着いてくれてうれしく思います。\n\nこれからさらに親しくなれるのを楽しみにしています。", 0x0b95857e, 0x5fb884e9, 0xe4a12cfa, nil, 0xb039551c, "...m." },
  [92701] = { "Valanaarへ", "Aonda's Written ReportをValanaarにいるValennia Stormfistに届けてください。", "ひとまず、パイロンも村も無事のようだ。そこで、この報告書をValanaarのValennia Stormfistに届けてほしい。Valanaarは島の南東の端にある。Valenniaは島の治安維持隊の長で、ここで何があったかを知っておく必要がある。\n\n教団は急速に勢力を広げていて、治安維持隊はこれまで直接の衝突を避けてきたが、そんな日々はもう終わりだ。Valanaarは戦いに備えなければならない。\n\nいずれにせよ、ありがとう。Shen'darにはいつでもお前の友がいるぞ、{name}。", "Aondaからの手紙か。あの抜け目のない高地の民は、何をたくらんでいるんだ？", "<手紙を読むうちに、Valenniaの表情が曇っていく。>\n\nAondaはこれを届ける役をあなたに託したし、この手紙でもあなたのことをかなり高く評価している。だから私もあなたを信じてみよう。話を進める前に、ここに残っているわずかな治安部隊員と相談して、教団が次にここを襲ってきた場合の計画を立てなければならない。今はValanaarでの滞在を楽しんでくれ。\n\n何かすることを探しているなら、あなたのような強い若い冒険者の助けを必要としている町の人々がたくさんいるだろう。", 0x74fef55e, 0x117fb641, 0x1bb0140d, 0xc4bd4279, 0xd674e12c, "....." },
  [92703] = { "知らせの配達", "ValanaarにいるAlvarion Windfieldと話してください。", "これだけのことがあったのに、あなたをよそ者と呼び続けるのはどうもしっくりこないわね。だから……ありがとう、{name}。\n\nもしよければ、そっちへ戻ることがあったら、ここで何があったかAlvarionに伝えて。それと、あの人が立てるようになったら、windshaperを一人ここへ連れてきて、あの構造体を調べてもらうよう言って。私たちの……私たちの家族のそばに置いても安全か確かめたいの。\n\n<Aameliaがそっとお腹に触れる。>\n\nこのことはあの人は知らないの。今はここだけの話にしておきましょう。", nil, "<果樹園で起きたことを話し終えると、Alvarionの目に涙が浮かぶ。>\n\nどう礼を言えばいいのか分からないよ、友よ。私は希望を求めてValanaarへ来た。むなしい希望だと、ほとんど確信していた。でも代わりに、英雄に出会えた。Skywallへ来る前の物語に出てくるような、本物の英雄に。\n\n君がしてくれたことは決して忘れないよ、{name}。Windfield家はいつでも君を歓迎する。", 0xa7d041e9, 0xd93e176f, 0x41c99c84, nil, 0x57d677d5, "...m." },
  [92706] = { "お尋ね者：Bruuz", "Bruuz's Dorsal FinをRatchetにいるGazloweのところへ持って行ってください。", "釣り人諸君に告ぐ！\n\n巨大なサメが船着き場近くの海域を回遊し、船乗りや小舟を襲っている。港湾労働者たちはそいつに「Bruuz」というあだ名をつけた。そのヒレを持ってきた者には、たっぷりと報酬を出すぞ！\n\n-- Gazlowe", "何か用かい、{race}？", "やっと誰かがあいつを仕留めてくれたか！町のみんながしょっちゅう「サメだ！」って叫んでる時に、船員を水に出すのがどれだけ大変か分かるか？\n\n最後に笑ってやるために、今夜の夕食はあの化け物のヒレをスープにしてやろうかな。", 0x63f4d985, 0xf267f662, 0xc0d6b34c, 0x98361c3d, 0x66e7198a, "....." },
  [92707] = { "巣穴の巨人", "Goliath's WristguardsをHammerfallのDrum Felに届ける。", "巨大な死骸からもぎ取った、その巨人のbracersはとてつもなく大きい。あなたの腕が肩まで、縁に触れることなくすっぽり通るほどだ。\n\nこれを警告としてHammerfallへ持ち帰るべきだろう。Drum Felは自分が何を相手にしているか知っておくべきだ。", nil, nil, 0x97265d43, 0x8a910368, 0x97fb37e9, nil, nil, "...mm" },
  [92708] = { "大冒険", "Ayessa Dawnsingerの話を聞いてください。", "Windshapersは、Zephras Isleの今の危機に対処しようと懸命に取り組んできました。消えた風の精霊を探すなかで、驚くべき発見がいくつもあり、今は島を救う手立てを得られるかもしれない行動計画を練っているところです。\n\nですが、これを成功させるには、あなたのような力ある若い冒険者が必要です。どうか、少しお時間があれば、この件についてもっとお話しさせてください。", nil, "これで分かったでしょう？Skywallの外には、知識とまだ手つかずの可能性に満ちた世界があるのです。ここが私たちの故郷であることは決して変わりません。ですが、私たちの救いへの道は下にあると信じるようになりました。私たちはAzerothへ旅立ち、Zephras Isleを救うための力と手段を手に入れなければなりません。これこそが進むべき道です。\n\nその時が来たら、私たちに加わる勇気はありますか？", 0xd900e63a, 0x9a2edad6, 0x4a6064f1, nil, 0x1a982773, "...m." },
  [92709] = { "大冒険", "ValanaarにいるElaadrin Evengaleの話を聞いてください。", "あなたのhighborneの血筋は、頭上の空のようにはっきりとその瞳に輝いています。あなたは私たちの仲間です。私たちの故郷を救う助けとなるのは、あなたのような若者たちなのです。ですがまずは、ここZephrasでの……そしてその先での、私たちの使命と計画について、もっとお話しさせてください。", nil, "これで分かりましたか？祖先の古き魔法を再発見することこそ、Zephras Isleの秘密を解き明かし、私たちの未来を確かなものにする鍵です。しかし故郷を救うには、この数千年の間に失ったものを再発見しなければなりません。\n\nAzerothこそが鍵です。Kirin Torが道を示してくれるでしょう。\n\n私たちが出発の準備をする間に、ここValanaarにいるHigh Orderの他のメンバーにも顔を出しておくといいでしょう。その多くが、あなたのような人の助けを借りてやり遂げたい仕事を抱えています。", 0xd900e63a, 0x8e1740b2, 0x2d2692fd, nil, 0x7ee53658, "...m." },
  [92727] = { "行方不明の学者", "Fillion Flamebreezeの身に何が起きたのか突き止めてください。", "知識の探求はHigh Orderの第一の使命ですが、この仕事が今のZephrasほど危険だったことはありません。\n\n我々の学者の一人、Fillion Flamebreezeは、Shen'dar Highlandsの一部の地域に集まる風の魔法について調査するため、そこへ向かう途中でした。残念ながら彼は戻っておらず、道中で何かあったのではと案じています。\n\nできることなら、彼を探し出してください。最後に目撃されたのは、ValanaarからShen'dar Highlandsへ西に向かう道の上でした。", nil, "<目の前に置かれた鞄のふたに、乾いた血のように見える染みがいくつか付いている。その染みを調べていると、ふたに名前が刺繍されていることにも気づく。「Fillion Flamebreeze」と書かれている。>", 0xa1e8590e, 0xd1671205, 0x24478d54, nil, 0xd7bd3645, "...m." },
  [92741] = { "招かれざる訪問者", "Shadowgale Forestへ行き、ValanaarにいるIaadaria BitterwindのためにShriekling Talonsを8個集めてください。", "Shadowgale Forestはとてつもなく危険で、普通の冒険者は通常立ち入りを禁じられています。ここ数か月でshrieklingの数が爆発的に増え、森の外へ縄張りを広げ始めていて、問題になりかねません。私はshriekling talonsの錬金術的な性質に関心があるので、どうしても必要な間引きは、学術的な収穫を得る機会でもあるのです。\n\nShadowgale Forestへ行って、その獣を狩ってください。できるだけ多くの爪を持ってきてください。", "High Orderは、ただの罠師や猟場番として働くことを習慣にはしていない。だが、このような奉仕が学術的な成果につながるなら、喜んで地域への奉仕活動に携わろう。", "ずいぶんたくさんの鉤爪を持ってきてくれましたね。早く調べたくてたまりません！\n\nHigh Orderへの貢献に感謝します、{class}。", 0x3ef89823, 0xc2afbc22, 0x9ce8f981, 0xa68815e1, 0x798df088, "....." },
  [92742] = { "井戸の調査", "Well Water Sample Kitを使って、Jansen SteadとMolsen Farmの井戸から水のサンプルを採取してください。", "この地を蝕む毒の源と正体を突き止めねばならない。まずはこの辺りの農場の地下水から始めよう。\n\n北のJansen Steadと、ここから北西のMolsen Farmへ行き、そこの井戸から試料を集めてくれ。", "サンプルは集めたか？", "ありがとう。どれどれ……", 0x1754ed02, 0xbfaa968d, 0x8ee73e39, 0xf98dff5c, 0x9913f7d5, "....." },
  [92743] = { "Conqueror's Crown", "Magramとの評判を維持し、BadlandsからConqueror's CrownをMagram VillageのWarugのもとへ持ち帰る。", "この地で最強のcentaur氏族として、我らには、その力にふさわしい獰猛さを持つ武具こそふさわしい！\n\n何よりもWarugに必要だ。兜……いや、crownだ！conqueror's crownだ！海の向こうの恐ろしい征服者の伝説を聞いたことがある。Badlandsと呼ばれる地へ行き、そこにある墓所を探せ。crownを見つけるまで戻ってくるな。\n\nこれを成し遂げれば、Magramの最大の力を明かしてやろう。", nil, nil, 0x113cbd89, 0xdd9d5673, 0x785d75a9, nil, nil, "...mm" },
  [92744] = { "Murlocのエラ", "Alba Fairmoonは、Westfallの海岸線沿いでLongshore Murloc Gillを7個集めてほしいと言っています。", "Westfallの作物を冒している汚染は、海にもしみ出しているかもしれません。地元の魚まで影響を受けていたら、Stormwindは飢饉に見舞われかねません。\n海岸沿いのmurlocsからgillsを集めて、持ってきてください。Murlocsはとても丈夫ですが、その体は汚染物質に非常に敏感です。海水に毒があれば、集めたgillsにはっきり表れるはずです。", "murlocsにあまり苦労させられなかったでしょうか？", "なるほど……このエラは今のところ健康なようです。ですが、油断してはなりません。", 0x18d085b1, 0x82b38f95, 0x84c4b3d3, 0xebb50726, 0x6a17bd1b, "....." },
  [92745] = { "鉱山の状況", "Jangolode MineでKobold Diggerを4体、Gold Coast QuarryでRiverpaw Minerを6体倒してください。", "集めてくれた井戸の試料には有毒な金属が含まれています！ この汚染をすぐに止めなければ、この土で再び作物が育つまで何十年もかかるでしょう。\nDefiasがWestfallの鉱山を占拠し、生き物を働かせて資源を奪い取っています。北のJangolode Mineと西のGold Coast Quarryで奴らの鉱夫を倒して、邪魔をしてください。", nil, "よくやってくれました、{name}。ですが、毒の源はどこか別の場所にあるのではないかと心配です……", 0xdbfbda3d, 0xb4f30bb0, 0x0ed0182f, nil, 0x1b6794e0, "...m." },
  [92747] = { "Moonbrookの諜報活動", "MoonbrookからSuspicious Industrial Suppliesを8個集めてください。", "妙ですね――毒はあなたが調べた鉱山から出ているのではないようです。\n\nMoonbrookの町の下にあるDeadminesはWestfallで最も大きく深い鉱山だと聞いていますが、First War以来放棄されています。Deadminesが再び動いているのでしょうか？\n\nMoonbrookへ行ってください、{name}。採掘や工業活動の証拠を探してください。これが我々に残された最後の手がかりです！", "何か見つかったか？", "これは一体何だ？", 0xd607718d, 0x576e6434, 0xbc34590a, 0x2e14d88f, 0xb7fab352, "....." },
  [92748] = { "爆発物の相談", "StormwindのDwarven Districtへ行き、力を貸してくれる技師を見つけてください。", "あなたが見つけた物資は、Deadminesのどこかで大規模な工業作業が行われていることを示しています。これがWestfallの農地を苦しめている毒の出どころであることは間違いありません。すぐに止めなければ。\n\nあそこにあるものは、壊すのが難しいでしょう。StormwindのDwarven Districtへ行き、爆薬を用意してくれる技師を見つけてください。", nil, "何か吹っ飛ばしてほしいのかい？", 0x35aa9cd8, 0x37ec6835, 0x6c61d133, nil, 0x8969accc, "...m." },
  [92749] = { "ダイナマイト作戦", "製作、取引、またはオークションハウスでCoarse Dynamiteを10個手に入れ、StormwindのDwarven DistrictにいるSprite Jumpsprocketのところへ戻ってください。", "産業破壊工作？ 興味が湧いたぞ！\nまずはdynamiteから始めよう……", "その爆薬を見せてくれ、{name}！", "幸先のいいスタートだ！あとは全部まとめて……ちょっとだけ刺激を足して……", 0xdbe7a3f6, 0x66c49bdc, 0x9f9816fe, 0x9f4c0c1a, 0xb7dd7511, "....." },
  [92750] = { "遠隔からの爆破", "遠隔起爆装置の入手について、Stormwind Intelligenceの誰かと話してください。", "「制御された」爆発がお望みってわけか？そんなに面白くはないけど、手足を全部残しておきたいなら賢い選択だな。\nあいにく遠隔起爆装置は持ってないんだ。Stormwind Intelligenceのこそこそした連中のところで聞いてみたらどうだ？何か見つけてくれるはずさ。", nil, "ふむ……何か特定の物を探しているのかい？", 0x9e430b80, 0x2e22edaa, 0xe691f760, nil, 0xe2f54704, "...m." },
  [92751] = { "遠隔からの爆破", "Remote Detonator KitをStormwindのDwarven DistrictにいるSprite Jumpsprocketのところへ持って行ってください。", "何かを破壊したいって？それはMoonbrookでのお前の動きと関係があるのか？驚いた顔をするな。SI:7はStormwindの領内で起こることはすべて把握している。\n\nWestfallの地下の洞窟で爆発を起こすつもりなら、事前に十分外へ出ておくことだ。この遠隔起爆装置を持っていけ。うちの技術者たちが作ったばかりの試作品だ。\n\nああ、それと、私が関わったことはお前のエルフの友には言わないほうがいいだろう。", nil, "いいぞ、それこそ必要な起爆装置だ！", 0x9e430b80, 0xecf85250, 0xc3fa1845, nil, 0x4868f6f1, "...m." },
  [92752] = { "爆発物の相談", "WestfallにいるAlba Fairmoonのところへ戻ってください。", "よし、爆弾の準備はできた！その起爆装置の扱いには気をつけろよ。", nil, "戻ってきてくれてうれしいよ、{name}。", 0x35aa9cd8, 0x767de34f, 0xeac04347, nil, 0x10bfbc2a, "...m." },
  [92753] = { "Deadminesでの破壊", "Deadminesに隠された鍛冶場を見つけ、その近くにExtra-Destructive Explosivesを仕掛けてください。それから、Deadminesの出口でAlba Fairmoonと落ち合ってください。", "毒の発生源は、おそらく何らかの大型の冶金用の炉だ。Deadminesへの入り口を見つけて炉を突き止め、爆薬を仕掛けてくれ。\n私はMoonbrookの裏の丘で待っている。戻ってきたら、爆薬を起爆しよう。炉がなくなれば、この地も癒え始めるだろう。", nil, nil, 0x7e9a4fff, 0x13b8e5d8, 0xc733c35a, nil, nil, "...mm" },
  [92754] = { "影からの防護、新たな需要", "Magramとの評判を維持し、Greater Shadow Protection Potionsを$N1個、DesolaceのMagram VillageにいるMirdaに届ける。", "我らの氏族の仲間たちは、さらに南へ、呪われたValley of Bonesとその先へと進み続けている。\n\nお前は我らの氏族に認められてはいるが、彼らの遠征の詳細を明かすほどお前を信用してはいない。どのみち、よそ者のお前には退屈な話だろう。\n\nお前に関わるのは、彼らが生き延び続けるためにGreater Shadow Protection Potionsが大量に必要だということだ。それを持ってくれば、お前のことを良く言っておいてやろう。", nil, nil, 0x687ae999, 0xb5521b2f, 0xa57a9cc9, nil, nil, "...mm" },
  [92755] = { "謎めいた神秘", "Gelkisとの評判を維持し、Greater Mystic Essencesを$N1個、DesolaceのGelkis VillageにいるHaleaに届ける。", "日を追うごとに、我らの漁り屋たちが倒れた冒険者から持ち帰る武具は減る一方だ。\n\nその品を直接使うことはできないが、素材として回収している。最も魔力の強い武具は私のもとへ来る。私はそれを分解し、その不思議な残滓を使って我らの武器に、特に我らのウィンドチェイサーの武器に魔力を付与できるのだ。\n\n次の襲撃隊に価値ある装備を用意するには、Greater Mystic Essencesが必要だ。", nil, nil, 0x7a268f3c, 0xe6a3f066, 0x69bc1d33, nil, nil, "...mm" },
  [92814] = { "仕立て屋が必要だ", "Gelkisとの評判を維持し、White Bandit MaskをDesolaceのGelkis VillageにいるMolkarに届ける。", "私のつがいのHaleaは、我らの武具にふさわしい魔力を込める役目を負っている。\n\n付与魔法というもの自体、私の理解をはるかに超えているが、村の物資と装備を整えておくのが役目のcentaurとして、Haleaが役目に遅れがちなのは知っている。彼女のせいではないのだがな。\n\n彼女が技を練習できるよう、簡単な衣服を贈りたい。砂嵐の中を簡素なfacemasksをつけてさまよう冒険者たちを見かける。いくつか手に入れてきてくれないか？", nil, nil, 0xd86e3465, 0x683448f5, 0x2e330903, nil, nil, "...mm" },
  [92817] = { "革の技法", "Gelkisとの評判を維持し、Barbaric HarnessをDesolaceのGelkis VillageにいるTalraに届ける。", "胸を刃や矢で貫かれて数多くの犠牲を出しているというのに、Gelkisの氏族仲間に鎧を着させるのはほぼ不可能だ。\n\n私は、彼らが文句を言う「チクチクする」感じのない、それなりの防御力を持つベストの設計を任されている。物資は乏しいから、貴重な革をがらくたに無駄遣いするわけにはいかない。\n\nよそ者よ、野蛮なcentaurに合うharnessを持ってきてくれないか？お前の技術から学びたいのだ。", nil, nil, 0xe1654f2c, 0x78d11657, 0xe5dbca65, nil, nil, "...mm" },
  [92818] = { "大きな、いや、巨大な鉄の斧", "Magramとの評判を維持し、Massive Iron Axesを$N1本、DesolaceのMagram VillageにいるGrolkarに届ける。", "もっと武器がいる。\n\nもっと。武器を。\n\nMAGRAMがどうやって貧弱なGELKISを叩き潰すというのだ？\n\nお前に何が作れるか見せてみろ、よそ者。斧を持ってこい。でかいやつ、いや、とてつもなくでかいやつだ。\n\n急げ。", nil, nil, 0x1c3f85ce, 0x4f5d09f2, 0xdfe891b2, nil, nil, "...mm" },
  [92819] = { "Deadminesでの破壊", "起爆装置を使う。", "もうすぐ終わりだ。起爆装置を使って、決着をつけろ。", nil, nil, 0x7e9a4fff, 0x8e3775bb, 0x06a779b6, nil, nil, "...mm" },
  [92834] = { "十倍の報復", "Valanaarの北にあるGustberry FieldsまたはShrine of AkirにいるAl'Akethの教団員から、Al'Aketh Windstone Charmを10個集めてください。", "教団が暴力の活動を始めたとき、PeacekeepersとWindshapersは威嚇で応じた。私はそれを愚かな事態の悪化だと考え、平和的な対話を訴えた。昨日、私は友人のBelathaan BrightwishをShrine of Akirへ送り出した。その対話の道を開けることを願って。\n\nつい先ほど、銀色の顔料に浸されたBelathaanの舌が入った箱が届いた。\n\n教団とは話し合いの余地などないと、今ではよく分かった。目にした教団員は一人残らず殺し、奴らが持っている祈りのお守りを持ってきてくれ。", "Windshapersとはあまり意見が合わないが、Al'Akethと平和的に関わろうという考えを退けたのは正しかった。高潔な道を選ぼうとした私の試みは大切な友の命を奪い、私が残りの人生ずっと背負っていかねばならない過ちとなった。", "High Orderは実利と論理を誇りとしています。そして論理に従えば、たいていの場合、争いと命の損失を避けることが最も賢明な選択です。\n\n<Elaadrinの目が輝き始め、秘術のエネルギーがぱちぱちと弾ける。>\n\n……しかし、教団は私たちの慎重さを弱さと取り違えました。その過ちの代償を払う覚悟など、彼らにはまるでできていないのです。", 0xe040942e, 0xd3397555, 0x7ba9539f, 0x93e0875d, 0x12ebcdcd, "....." },
  [92840] = { "風をつかむ", "Index EsoteriaをShen'dar HighlandsのOverlook Standing Stonesへ持って行き、周辺のWindstone Formationsに使ってデータを集める。", "Fillionは、そこにあるエレメンタルのエネルギーを測定し研究するための特別な装置を持って、Overlook Standing Stonesへ送られた。\n\nこれを持っていけ――Index Esoteriaだ。これを使って、あそこにそびえる巨大なwindstoneの岩層からデータを引き出してくれ。ただし用心しろ。Windshaperたちが今ごろこの場所を躍起になって守っているだろうからな。\n\n邪魔しようとする者がいたら、まあ……必要なことをするといい。奴らの妨害にはもう我慢ならん。", "WindshapersとAl'Akethを見分けるのは、私にはしばしば難しい。違いといえば、一方が他方よりもあからさまに暴力的だということくらいだ。どちらも見当違いの信仰に同じように盲従しており、放っておけばどちらも同じように危険だ。\n\n奴らは、この世界とその魔法をより深く理解したいという我らの願いを、自分たちの伝統への冒涜とみなしている。その狭量さこそ、我らの使命が重要な理由だ。我らでなければ、誰がZephrasを救う勇気を持つというのだ？", "Windshaperの血を流すのは本意ではありませんでした。ですが、この無意味な争いの責任はすべて彼らにあります。私たちは平和的に情報を集めようとしたのに、彼らは暴力で応じたのです。\n\n残念ながら噂は広まり、Windshapersはすでにこれを「虐殺」と呼んでいます。ここValanaarで報復する度胸はないでしょうが、決して忘れはしないでしょう。\n\n{name}、あなたはHigh Orderにとって大きな助けとなってくれました。ありがとう。", 0x24fe5981, 0x3d378073, 0x1389f90b, 0x5ad6771e, 0x6f9df3cd, "....." },
  [92841] = { "Valley of Bones", "Magramとの評判を上げ、Magram Villageの南にあるValley of Bones近くでOrgrulを探し出す。", "よそ者よ、我らの大いなる発見を知る時が来た……だが、それを語るのはWarugではない！\n\n村の反対側、南へ向かえ。Orgrulという名の、でかくて臭いcentaurを探せ。\n\nそこに着けば分かる。\n奴を見れば分かる。\nお前が知るに値すると奴が思えば、お前は知ることになる。\n\nもし思わなかったら？まあいい。Warugが新しい冠を手に入れたことを喜んでおけ。", nil, nil, 0x1c23f49e, 0xe0ffefcb, 0xea834bb9, nil, nil, "...mm" },
  [92844] = { "骨の山", "Magramとの評判を維持し、Gently Cursed Bonesを$N1個、DesolaceのMagram Villageの南にいるOrgrulに届ける。", "何らかの死霊術のエネルギーがValley of Bones中に染み渡っている。理由は我らにもまだ分からん。\n\nその理由も我らにはどうでもいい。この魔法は今や我らのものだ。刃や槌で戦わぬ者は、この新たな魔法の訓練を受けている。\n\n手始めに難しい仕事を任せるつもりだと思っているなら、考え直せ。今のところは、Valley of Bonesへ行って、bonesをいくらか取ってこい。お前にもそのくらいはできるだろう。", nil, nil, 0x87f6217c, 0x119ae063, 0xf8d93bb4, nil, nil, "...mm" },
  [92846] = { "Outcast Necromancers", "Magramとの評判を維持し、Valley of Bones内でOutcast Necromancersを倒す。", "このあたりをのし歩いている貧弱なcentaurに気づいたか？あれはGelkisの血筋の者どもだ。\n\n我らMagramは、すでに峡谷の奥深くに足場を築いている。Gelkisがここにいる我らに気づくと、奴らの中には我らの後を追う者が出てきた。奴らが我らに加わりたいのか、我らを倒そうとしているのかは知らん。だが、奴らの氏族仲間が奴ら全員に追放を言い渡したことは知っている。\n\n奴らは、自分たちのものではない力に手を出す一匹狼だ。奴らには死んでもらいたい。", nil, nil, 0xfacd5ea6, 0xf4045ba9, 0xed11a5fa, nil, nil, "...mm" },
  [92847] = { "堕落させる涙", "Magramとの評判を維持し、Petrified Barkを$N1個とImbued Tearsを$N2個、Orgrulのもとへ持ち帰る。", "よそ者よ、追放された死霊術師どもが手にしていた武器に気づいたか？Gelkisが死霊術の道を極めるほど長く生きられぬよう我らが手を打つが、奴らの力の導き方には興味を惹かれた。奴らは、Warugがお前に盗ませたのと同じ水晶まで使っている。\n\nこの技法は我らの役に立つと思う。谷へ戻って呪われた木々から木材を取り戻し、Warugが水晶を少し分けてくれるか確かめてこい。それで杖を作ってやろう。", nil, nil, 0x79a08fa8, 0x4a5b92ad, 0x792146f7, nil, nil, "...mm" },
  [92849] = { "行方不明の学者", "Fillion Flamebreezeを探し続けてください。", "<今見つけたものから判断すると、Fillionがここで何らかの災難に見舞われた可能性は非常に高い。彼はまだ近くにいて、助けを必要としているかもしれない。今いる場所のすぐ北に洞窟があることに気づく。そこで彼の捜索を続けるべきだろう。>", nil, "あ……ありがとう、旅の人。Overlook Standing Stonesでの任務から戻る途中、突然Windshapersに待ち伏せされて襲われたんだ。奴らは私を洞窟の入り口まで無理やり連れて行き、意識も朦朧として血を流したまま置き去りにした。気を失う前に最後に覚えているのは、巨大な翼のある獣が洞窟から出てきて、私をすくい上げたことだ。\n\n君が来てくれなかったら、私はあの獣とその子供たちの夕食になっていたと言っても過言じゃないだろう。", 0xa1e8590e, 0x1851c7de, 0xba014091, nil, 0xc5136b37, "...m." },
  [92850] = { "行方不明の学者", "Shriekling DenでShriekling Matriarchを倒し、その首をValanaarのFillion Flamebreezeのところへ持ち帰る。", "もうずいぶん楽になりました。私には多少の秘術の心得がありますし、ここからValanaarまではほんのわずかな距離です。一人で戻れます。それに、私の身の安全よりも大事なのは、このshrieklingたちがValanaarのこれほど近くに巣を作っていること、そしてそれがもたらす危険です。よろしければ、もう一度中へ戻って、あの獣の首を取ってきてください！\n\nそれが済んだら、私はValanaarに戻っています。ここで起きたことと私の任務の状況を、Supreme Magisterに報告しなければなりません。", "あのshrieklingsがValanaarのこんな近くに巣を作るのを放っておくのは危険すぎる。だが……奴らなど、我らの悩みの中では取るに足らないものだ。", "改めてありがとう、{name}。", 0xa1e8590e, 0xbe3aeb06, 0x74495b96, 0xa39befbf, 0xef8e99bb, "....." },
  [92860] = { "Zephrasに仕えて", "Valennia Stormfistに報告し、Al'Akethとの戦いでHigh Orderが彼らと共にあることを伝えて下さい。", "High Orderは教団との直接の衝突を避けようと最善を尽くしてきましたが、それはもはや明らかに選択肢ではありません。奴らの敵意ははっきりと示されましたし、今では島のあちこちで、教団がより大規模に動いているという噂もあります。奴らは明らかに何かに向けて準備を進めていて、それが何であれ、Zephrasの民にとって良いことであるはずがありません。\n\nValennia Stormfistのもとへ報告に行き、必要とあらば、High OrderはAl'Akethに対するValanaarの取り組みを全面的に支援すると伝えてください。", nil, "Belathaanのことは残念だ。実は彼は私のいとこで、優れたメイジであり、Zephrasに仕える者だった。我々が必ず仇を討つ。\n\nすぐにでも力を貸したいようだな。さあ、今の状況についてさらに話そう。", 0x81e9cbc4, 0x1fd448de, 0xae75fd2c, nil, 0xbacbd841, "...m." },
  [92871] = { "Zephrasに仕えて", "Valennia Stormfistに報告し、Al'Akethとの戦いにおいてWindshapersが彼らと共にあると伝えてください。", "Valennia Stormfistと彼女の治安維持隊は、昔からZephrasの守り手であり、私たちもできる限り力を貸してきました。島のあちこちで教団がより大規模に動いているという噂があり、彼らは明らかに何かに向けて準備を進めています。\n\nValenniaのもとへ報告に行き、必要とあらば、WindshapersはAl'Akethに対するValanaarの取り組みを全面的に支援すると、改めて伝えてください。", nil, "すぐにでも力を貸したいようだな。さあ、今の状況についてさらに話そう。", 0x81e9cbc4, 0x0b60fad2, 0x2e47c801, nil, 0xbbe87049, "...m." },
  [92873] = { "概念実証", "Magram Clanとの評判を維持し、成功した儀式で得たWell Cursed Bonesを$N1個、Orgrulのもとへ持ち帰る。", "この水晶が大地を裂く以上のことができるのは、すでに分かっている。Gelkisが、死霊術の力のために歪められることを証明したのだからな。お前に集めさせた骨を覚えているか？この丘のすぐ上で、できる限り組み上げておいた。使えるスケルトンを2体作るには十分だった。\n\n<Orgrulは作ったばかりの杖をあなたに手渡す。>\n\nお前が新しいおもちゃで遊んでいる間に、私はNecrokhanの杖を届けてくる。使い方が分かったと証明できたときにだけ戻ってこい。", nil, nil, 0xf4d241cb, 0x58f13948, 0xc33d5418, nil, nil, "...mm" },
  [92880] = { "Valanaarのもとへ", "Yorna's ReportをValanaarのValennia Stormfistに届けてください。", "攻撃してきた連中の残りを片付けるには少し時間がかかりそうだが、今なら我々の勝算はずっと高い。Valanaarへ戻って、ここはもう安定したと伝えてくれ。\n\n君の助けには感謝してもしきれない。君がいなかったら、ずっとひどい状態になっていただろう。援軍を頼んだら、代わりに成長著しい英雄が来たようだ。それで十分だ。\n\n4つの風が君を祝福せんことを、{class}。", nil, "<東の見張り塔の様子を伝えると、Valenniaは目に見えて安堵する。>\n\n風に感謝を。", 0x50dc0d7e, 0xb15128d3, 0x1556d10a, nil, 0xa8b56e05, "...m." },
  [92881] = { "大長老の頼み", "ValanaarのTalaanis Shadowsongと話してください。", "西と東の両方の見張り塔が襲われたのは偶然ではない。西の見張り塔でskypriestについて起きたことを君から聞いた限りでは、教団はアンカーパイロンに何かをしようとしている、というのが我々の一番の見立てだ。\n\nHigh Elder Shadowsongと話してくれ。有望かもしれない手がかりについて教えてくれるだろう。", nil, "ちょっとした用事があるんだが、まさにあなたのような冒険者が提供できる類の手助けが必要なんだ。", 0xb3d882cd, 0x4440ff8a, 0x4ba0a7fd, nil, 0xd03f5c14, "...m." },
  [92893] = { "弱者に慈悲なし", "Magram Clanとの評判を維持し、Valley of Bonesの各地にいるGelkis Captivesを$N1体倒す。任務を終えたらOrgrulのもとへ戻る。", "Valley of Bonesのさらに奥へ踏み込めば、我らの縄張りに入り込んだGelkisの放浪者たちが見つかるだろう。そこらを掘り進む骨虫どもの餌にできるよう、生かしておけと指示したのだが、虫どもは獲物が生きていることに興味がないらしい。\n\n仕事は単純だ。捕虜を見つけ、その命を断て。自由へのかすかな希望すら抱かせるな。", nil, nil, 0x384f234f, 0xa451dbd7, 0x70ca071f, nil, nil, "...mm" },
  [92894] = { "骨の蘇生", "Magram Clanとの評判を維持し、Enhanced Necromancy Staffを使って、Valley of Bonesの各地で這い出そうともがいているアンデッドを完全に蘇らせる。Magramの軍が大きくなったらOrgrulのもとへ戻る。", "お前の目に興奮が見えるぞ、よそ者。死霊術の可能性がもう分かったか？\n\nもちろん分かっているだろう。だからこそ、お前にさらに腕を磨くよう命じるのだ。\n\nValley of Bonesの奥へ進むと、死者を蘇らせる試みに失敗した残骸が見えるだろう。間違いなくGelkisの試みだ。土から這い出すこともろくにできん。哀れでなければ笑えるところだ。\n\nお前のstaffにより大きな力を込めておいた。これで我らの軍勢を増やし、歯向かう者どもを叩き潰せ！", nil, nil, 0x2ba21978, 0x13a123ec, 0x078c77e1, nil, nil, "...mm" },
  [92909] = { "収穫機からの収穫", "Saldean's FarmのOzwin Ironsprocketは、Golem Isospringsを14個とHarvester Gyrostabilizersを5個持ってきてほしいと言っています。", "ああ、しまった……こりゃまずいことになったぞ！\n\nWestfallの畑でharvestersが暴れていると聞いて、調整し直せないかと、はるばるIronforgeから来たんだ。でも、あいつらは私の計算よりずっと凶暴で、この厩舎まで追いかけてきたんだよ！\n\nharvestersからisospringsとgyrostabilizersを手に入れられれば、逃げるのを援護する装置を作れるんだが。部品を集めてきてくれないか？", "外はひどい有様だね、{name}！私の必要な部品は集めてくれた？", "本当にありがとう！脱出の計画に取りかかるよ。それまでの間、これを持っていって！", 0xced8714e, 0xb9cd3180, 0x7c112345, 0x86f9d0d9, 0x2ee3cde7, "....." },
  [92910] = { "収穫機からの収穫", "Precessive Autocognition AssemblyをSaldean's FarmのOzwin Ironsprocketに届けてください。", "harvesterから回収できたこの部品は、ほぼ無傷のようだ。harvest golemsに関心のある者なら見たがるかもしれない。", nil, nil, 0xced8714e, 0xd39b8561, 0x8ffaa4f3, nil, nil, "...mm" },
  [92911] = { "収穫機からの収穫", "Saldean's FarmのOzwin Ironsprocketは、Golem Isospringsを8個、Copper Modulatorsを4個、それにCrude Scopeを一つ持ってきてほしいと言っています。", "なるほど……これであの怪物どもがどう動いているのか少し分かったぞ。少なくとも一時的には、奴らのシステムを乗っ取る方法を思いついた。\n\n持ってきてくれた組立部品をもう少しいじってみる。その間に、装置の部品をかき集めてきてくれないか？", nil, nil, 0xced8714e, 0x7ea5662a, 0xb1fbfa85, nil, nil, "...mm" },
  [92947] = { "行動開始", "Al'Aketh Guardianを$N1体、Al'Aketh Spiritcallerを$N2体、Al'Aketh Blademasterを$N3体倒し、Shrine of AkirにいるHyusaa Quickbreezeに報告する。", "全員揃ったな、よし。精鋭の戦士を何人か聖堂の正面から突入させて、騒ぎを起こし陽動にさせた。その間に私がWindshapersとHigh Orderを率いて側面から攻め込む。\n\nうまくいけば、すぐに突破してHigh Priestessを倒せるはずだ。君は、中に入って頭をかち割り始めてくれ。騒ぎを起こしたら、聖堂の階段近くで私の副官、Hyusaa Quickbreezeと合流しろ。\n\n風が君を導かんことを、{class}。", nil, "ここまで来るのに必死で戦ってきたが、まだ終わってはいない。", 0x688633bd, 0x590637a2, 0xe5240575, nil, 0xb4531928, "...m." },
})
